-- ==============================================================================
-- DỰ ÁN: TAROTCUAHALLE
-- FILE: Sample_Data.sql
-- MÔ TẢ: Dữ liệu nạp mẫu (Seed Data) chuẩn MySQL cho bảng TarotCard và ReadingSession
-- TÍCH HỢP TRỌN BỘ 78 LÁ BÀI TỪ 3 NGUỒN TRI THỨC CỐT LÕI:
--   1. Tarot Chú Giải (Từ khóa, nghĩa xuôi, nghĩa ngược)
--   2. Hành Trình Tarot (Câu chuyện nguyên mẫu & Yes/No lý giải tâm lý)
--   3. Dự đoán thời gian trong Tarot - Philippe Ngô (Mốc thời gian dự đoán)
-- ==============================================================================

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

USE `tarot_db`;

-- ------------------------------------------------------------------------------
-- 1. NẠP DỮ LIỆU TOÀN BỘ 78 LÁ BÀI TAROT VÀO BẢNG: TarotCard
-- ------------------------------------------------------------------------------
-- [1/78] major-0: The Fool (0. Chàng Khờ (The Fool))
INSERT INTO `TarotCard` (`card_id`, `name_vi`, `name_en`, `arcana_type`, `suit_element`, `keywords`, `upright_meaning`, `reversed_meaning`, `archetype_story`, `yes_no_result`, `yes_no_reason`, `time_prediction`, `image_path`) VALUES ('major-0', '0. Chàng Khờ (The Fool)', 'The Fool', 'Major', 'Khí', 'Khởi đầu mới, Sự ngây thơ, Tự do phiêu lưu, Tiềm năng vô hạn', 'Báo hiệu một hành trình mới đầy hào hứng, tự do bước đi theo trực giác và niềm tin trong sáng mà không bị trói buộc bởi nỗi sợ hãi quá khứ.', 'Sự liều lĩnh thiếu tính toán, ngây thơ đến mức mù quáng, hoặc sự do dự không dám bước ra khỏi vùng an toàn.', 'Nguyên mẫu Đứa Trẻ Thần Thánh (Divine Child) và Linh Hồn Thuần Khiết. Chàng Khờ đứng trước bờ vực với cành hoa hồng trắng và chú chó nhỏ trung thành, tượng trưng cho bước khởi đầu can đảm của con người khi dấn thân vào cõi đời, không bị vấy bẩn bởi định kiến hay nỗi sợ hãi quá khứ.', 'MAYBE', 'Vũ trụ mở ra tiềm năng vô hạn nhưng kết quả phụ thuộc vào việc bạn có dám bước ra khỏi vùng an toàn và tin vào trực giác sơ khai hay không; chưa có gì định hình chắc chắn.', 'Bất ngờ, ngay tức khắc hoặc thời điểm chuyển giao mùa xuân.', 'assets/cards/the_fool.jpg') ON DUPLICATE KEY UPDATE `name_vi` = VALUES(`name_vi`), `name_en` = VALUES(`name_en`), `arcana_type` = VALUES(`arcana_type`), `suit_element` = VALUES(`suit_element`), `keywords` = VALUES(`keywords`), `upright_meaning` = VALUES(`upright_meaning`), `reversed_meaning` = VALUES(`reversed_meaning`), `archetype_story` = VALUES(`archetype_story`), `yes_no_result` = VALUES(`yes_no_result`), `yes_no_reason` = VALUES(`yes_no_reason`), `time_prediction` = VALUES(`time_prediction`), `image_path` = VALUES(`image_path`);

-- [2/78] major-1: The Magician (I. Pháp Sư (The Magician))
INSERT INTO `TarotCard` (`card_id`, `name_vi`, `name_en`, `arcana_type`, `suit_element`, `keywords`, `upright_meaning`, `reversed_meaning`, `archetype_story`, `yes_no_result`, `yes_no_reason`, `time_prediction`, `image_path`) VALUES ('major-1', 'I. Pháp Sư (The Magician)', 'The Magician', 'Major', 'Khí', 'Ý chí sáng tạo, Kỹ năng điêu luyện, Hành động quyết đoán, Hội tụ nguồn lực', 'Bạn đang nắm giữ đầy đủ tài năng, công cụ và nguồn lực để biến ước mơ thành hiện thực. Ý chí mạnh mẽ sẽ dẫn lối thành công.', 'Thao túng, ảo tưởng sức mạnh, lãng phí tài năng hoặc dùng sự khôn lanh vào mục đích không chính đáng.', 'Nguyên mẫu Người Sáng Tạo (The Creator / Magus) và Ý Thức Tỉnh Táo. Pháp Sư một tay chỉ lên trời, một tay trỏ xuống đất, trên bàn hội tụ đủ 4 biểu tượng Đất - Nước - Lửa - Khí, biểu thị năng lực biến ý niệm tinh thần thành hiện thực vật chất thông qua ý chí tập trung cao độ.', 'YES', 'Bạn đã hội tụ đầy đủ kỹ năng, công cụ và nguồn lực cần thiết; chỉ cần chủ động ra tay hành động là sẽ xoay chuyển cục diện thành công.', 'Rất sớm, ngay khi bạn bắt tay vào hành động / Chu kỳ sao Thủy (khoảng 1 - 2 tuần).', 'assets/cards/the_magician.jpg') ON DUPLICATE KEY UPDATE `name_vi` = VALUES(`name_vi`), `name_en` = VALUES(`name_en`), `arcana_type` = VALUES(`arcana_type`), `suit_element` = VALUES(`suit_element`), `keywords` = VALUES(`keywords`), `upright_meaning` = VALUES(`upright_meaning`), `reversed_meaning` = VALUES(`reversed_meaning`), `archetype_story` = VALUES(`archetype_story`), `yes_no_result` = VALUES(`yes_no_result`), `yes_no_reason` = VALUES(`yes_no_reason`), `time_prediction` = VALUES(`time_prediction`), `image_path` = VALUES(`image_path`);

-- [3/78] major-2: The High Priestess (II. Nữ Tư Tế (The High Priestess))
INSERT INTO `TarotCard` (`card_id`, `name_vi`, `name_en`, `arcana_type`, `suit_element`, `keywords`, `upright_meaning`, `reversed_meaning`, `archetype_story`, `yes_no_result`, `yes_no_reason`, `time_prediction`, `image_path`) VALUES ('major-2', 'II. Nữ Tư Tế (The High Priestess)', 'The High Priestess', 'Major', 'Nước', 'Trực giác sâu sắc, Bí ẩn tâm linh, Tĩnh lặng nội tâm, Tri thức ngầm', 'Hãy lắng nghe tiếng nói sâu thẳm từ trực giác và giấc mơ của bạn. Câu trả lời không nằm ở thế giới xô bồ bên ngoài mà ở sự lắng đọng nội tâm.', 'Bỏ qua trực giác mách bảo, có bí mật bị che giấu hoặc tâm trạng bất an vì đè nén cảm xúc quá lâu.', 'Nguyên mẫu Nữ Tính Huyền Bí (Anima) và Tiềm Thức Sâu Thẳm. Ngồi giữa hai cột trụ Đen - Trắng (Boaz & Jachin) cùng bức màn quả lựu, Nữ Tư Tế canh giữ cánh cổng tri thức tâm linh, nhắc nhở con người về sự tĩnh lặng và lắng nghe trực giác trước khi hành động.', 'MAYBE', 'Câu trả lời đang bị ẩn giấu trong tiềm thức hoặc hoàn cảnh chưa bộc lộ hết; thời điểm này cần quan sát tĩnh lặng hơn là vội vã đưa ra quyết định.', 'Chu kỳ Mặt Trăng (28 ngày hoặc kỳ Trăng tròn tiếp theo).', 'assets/cards/the_high_priestess.jpg') ON DUPLICATE KEY UPDATE `name_vi` = VALUES(`name_vi`), `name_en` = VALUES(`name_en`), `arcana_type` = VALUES(`arcana_type`), `suit_element` = VALUES(`suit_element`), `keywords` = VALUES(`keywords`), `upright_meaning` = VALUES(`upright_meaning`), `reversed_meaning` = VALUES(`reversed_meaning`), `archetype_story` = VALUES(`archetype_story`), `yes_no_result` = VALUES(`yes_no_result`), `yes_no_reason` = VALUES(`yes_no_reason`), `time_prediction` = VALUES(`time_prediction`), `image_path` = VALUES(`image_path`);

-- [4/78] major-3: The Empress (III. Nữ Hoàng (The Empress))
INSERT INTO `TarotCard` (`card_id`, `name_vi`, `name_en`, `arcana_type`, `suit_element`, `keywords`, `upright_meaning`, `reversed_meaning`, `archetype_story`, `yes_no_result`, `yes_no_reason`, `time_prediction`, `image_path`) VALUES ('major-3', 'III. Nữ Hoàng (The Empress)', 'The Empress', 'Major', 'Đất', 'Phì nhiêu trù phú, Tình mẫu tử, Sáng tạo nghệ thuật, Nuôi dưỡng yêu thương', 'Năng lượng của sự thịnh vượng, dồi dào và sinh sôi nảy nở. Những nỗ lực của bạn sắp thu hoạch trái ngọt ấm no.', 'Sự ngột ngạt vì bảo bọc thái quá, phụ thuộc cảm xúc hoặc bỏ bê chăm sóc bản thân.', 'Nguyên mẫu Đại Mẫu (Great Mother / Mẹ Thiên Nhiên) và Năng Lượng Nuôi Dưỡng. Ngồi giữa cánh đồng lúa mì vàng óng và dòng thác mát lành, Nữ Hoàng đại diện cho sự thụ thai, phát triển trù phú, lòng bao dung và sự tận hưởng cái đẹp giác quan trọn vẹn.', 'YES', 'Năng lượng phì nhiêu, sinh sôi nảy nở đang bảo bọc dự định của bạn; mọi gieo trồng đều sẽ thu hoạch quả ngọt dồi dào.', 'Mùa xuân - Mùa gặt, hoặc chu kỳ thai nghén 9 tháng.', 'assets/cards/the_empress.jpg') ON DUPLICATE KEY UPDATE `name_vi` = VALUES(`name_vi`), `name_en` = VALUES(`name_en`), `arcana_type` = VALUES(`arcana_type`), `suit_element` = VALUES(`suit_element`), `keywords` = VALUES(`keywords`), `upright_meaning` = VALUES(`upright_meaning`), `reversed_meaning` = VALUES(`reversed_meaning`), `archetype_story` = VALUES(`archetype_story`), `yes_no_result` = VALUES(`yes_no_result`), `yes_no_reason` = VALUES(`yes_no_reason`), `time_prediction` = VALUES(`time_prediction`), `image_path` = VALUES(`image_path`);

-- [5/78] major-4: The Emperor (IV. Hoàng Đế (The Emperor))
INSERT INTO `TarotCard` (`card_id`, `name_vi`, `name_en`, `arcana_type`, `suit_element`, `keywords`, `upright_meaning`, `reversed_meaning`, `archetype_story`, `yes_no_result`, `yes_no_reason`, `time_prediction`, `image_path`) VALUES ('major-4', 'IV. Hoàng Đế (The Emperor)', 'The Emperor', 'Major', 'Lửa', 'Quyền lực uy nghiêm, Kỷ luật thép, Trật tự vững chắc, Khả năng lãnh đạo', 'Đại diện cho sự kiểm soát vững vàng, tư duy logic, cấu trúc kỷ luật và bản lĩnh đứng đầu che chở cho người khác.', 'Độc đoán, cứng nhắc bảo thủ, lạm dụng quyền uy hoặc thiếu năng lực tự chủ.', 'Nguyên mẫu Người Cha (The Father / Phụ Tính) và Trật Tự Xã Hội. Ngồi trên ngai đá chạm khắc đầu cừu uy nghiêm, Hoàng Đế biểu trưng cho lý trí vững vàng, tính kỷ luật, khả năng thiết lập ranh giới và bảo vệ đế chế của bản thân trước hỗn loạn.', 'YES', 'Tính thực tế, sự kỷ luật và cấu trúc rõ ràng sẽ giúp bạn làm chủ hoàn cảnh và đạt được kết quả như ý.', 'Mùa Bạch Dương (21/3 - 19/4) hoặc khoảng 4 tuần tới.', 'assets/cards/the_emperor.jpg') ON DUPLICATE KEY UPDATE `name_vi` = VALUES(`name_vi`), `name_en` = VALUES(`name_en`), `arcana_type` = VALUES(`arcana_type`), `suit_element` = VALUES(`suit_element`), `keywords` = VALUES(`keywords`), `upright_meaning` = VALUES(`upright_meaning`), `reversed_meaning` = VALUES(`reversed_meaning`), `archetype_story` = VALUES(`archetype_story`), `yes_no_result` = VALUES(`yes_no_result`), `yes_no_reason` = VALUES(`yes_no_reason`), `time_prediction` = VALUES(`time_prediction`), `image_path` = VALUES(`image_path`);

-- [6/78] major-5: The Hierophant (V. Giáo Hoàng (The Hierophant))
INSERT INTO `TarotCard` (`card_id`, `name_vi`, `name_en`, `arcana_type`, `suit_element`, `keywords`, `upright_meaning`, `reversed_meaning`, `archetype_story`, `yes_no_result`, `yes_no_reason`, `time_prediction`, `image_path`) VALUES ('major-5', 'V. Giáo Hoàng (The Hierophant)', 'The Hierophant', 'Major', 'Đất', 'Truyền thống, Lời khuyên thông thái, Học hỏi đạo lý, Cam kết quy chuẩn', 'Tìm kiếm lời khuyên từ người thầy dẫn dắt, tôn trọng các giá trị chuẩn mực và học hỏi tri thức từ những tổ chức uy tín.', 'Phá vỡ định kiến cũ kỹ, phản đối quy tắc lỗi thời hoặc bị mắc kẹt trong giáo điều mù quáng.', 'Nguyên mẫu Người Thầy Tâm Linh (The Mentor / Wise Old Man) và Truyền Thống. Ngồi giữa hai môn đồ với quyền trượng ba tầng, Giáo Hoàng đại diện cho hệ thống quy chuẩn đạo đức, sự truyền thừa tri thức và sự hòa nhập vào các cấu trúc xã hội chuẩn mực.', 'YES', 'Đồng thuận nếu bạn tuân thủ các nguyên tắc đạo đức chuẩn mực, làm theo lời khuyên của người có chuyên môn hoặc đi theo con đường chính thống.', 'Mùa Kim Ngưu (20/4 - 20/5) hoặc khoảng 5 tuần.', 'assets/cards/the_hierophant.jpg') ON DUPLICATE KEY UPDATE `name_vi` = VALUES(`name_vi`), `name_en` = VALUES(`name_en`), `arcana_type` = VALUES(`arcana_type`), `suit_element` = VALUES(`suit_element`), `keywords` = VALUES(`keywords`), `upright_meaning` = VALUES(`upright_meaning`), `reversed_meaning` = VALUES(`reversed_meaning`), `archetype_story` = VALUES(`archetype_story`), `yes_no_result` = VALUES(`yes_no_result`), `yes_no_reason` = VALUES(`yes_no_reason`), `time_prediction` = VALUES(`time_prediction`), `image_path` = VALUES(`image_path`);

-- [7/78] major-6: The Lovers (VI. Đôi Tình Nhân (The Lovers))
INSERT INTO `TarotCard` (`card_id`, `name_vi`, `name_en`, `arcana_type`, `suit_element`, `keywords`, `upright_meaning`, `reversed_meaning`, `archetype_story`, `yes_no_result`, `yes_no_reason`, `time_prediction`, `image_path`) VALUES ('major-6', 'VI. Đôi Tình Nhân (The Lovers)', 'The Lovers', 'Major', 'Khí', 'Tình yêu đích thực, Lựa chọn ngã rẽ, Sự hòa hợp tâm hồn, Giá trị đạo đức', 'Sự rung cảm mãnh liệt của hai tâm hồn đồng điệu. Đồng thời báo hiệu một ngã rẽ quan trọng đòi hỏi bạn phải chọn theo tiếng gọi trái tim.', 'Mất cân bằng, mâu thuẫn nội tâm, chia rẽ tình cảm hoặc đưa ra quyết định sai lầm do cảm tính.', 'Nguyên mẫu Sự Hợp Nhất Nhị Nguyên (The Conjunction) và Sự Thức Tỉnh Của Trái Tim. Dưới sự chúc phúc của Thiên thần Raphael, Adam và Eve đại diện cho sự hòa hợp giữa ý thức và tiềm thức, đồng thời đòi hỏi sự lựa chọn dũng cảm theo hệ giá trị cốt lõi.', 'MAYBE', 'Kết quả phụ thuộc vào việc bạn có chân thật với trái tim mình hay không; bạn đứng trước ngã rẽ và phải tự chịu trách nhiệm cho lựa chọn đạo đức của mình.', 'Mùa Song Tử (21/5 - 20/6) hoặc trong vòng 6 tuần.', 'assets/cards/the_lovers.jpg') ON DUPLICATE KEY UPDATE `name_vi` = VALUES(`name_vi`), `name_en` = VALUES(`name_en`), `arcana_type` = VALUES(`arcana_type`), `suit_element` = VALUES(`suit_element`), `keywords` = VALUES(`keywords`), `upright_meaning` = VALUES(`upright_meaning`), `reversed_meaning` = VALUES(`reversed_meaning`), `archetype_story` = VALUES(`archetype_story`), `yes_no_result` = VALUES(`yes_no_result`), `yes_no_reason` = VALUES(`yes_no_reason`), `time_prediction` = VALUES(`time_prediction`), `image_path` = VALUES(`image_path`);

-- [8/78] major-7: The Chariot (VII. Cỗ Xe Chiến Thắng (The Chariot))
INSERT INTO `TarotCard` (`card_id`, `name_vi`, `name_en`, `arcana_type`, `suit_element`, `keywords`, `upright_meaning`, `reversed_meaning`, `archetype_story`, `yes_no_result`, `yes_no_reason`, `time_prediction`, `image_path`) VALUES ('major-7', 'VII. Cỗ Xe Chiến Thắng (The Chariot)', 'The Chariot', 'Major', 'Nước', 'Chiến thắng vẻ vang, Ý chí kiên cường, Vượt qua thử thách, Tập trung mục tiêu', 'Sử dụng sức mạnh ý chí và sự tự chủ để chế ngự các mâu thuẫn đối nghịch, thẳng tiến về phía trước để giành lấy vinh quang.', 'Mất phương hướng, mất kiểm soát cảm xúc, bị cuốn theo tham vọng mù quáng hoặc kiệt sức.', 'Nguyên mẫu Người Hùng Chiến Thắng (The Hero). Chiến binh điều khiển cỗ xe với hai nhân sư trắng - đen bằng sức mạnh ý chí thuần túy chứ không cần dây cương, biểu tượng cho việc vượt qua các xung đột nội tâm để tiến thẳng đến mục tiêu vẻ vang.', 'YES', 'Ý chí kiên định và quyết tâm cao độ sẽ giúp bạn đập tan mọi trở ngại phía trước; chiến thắng thuộc về người chủ động.', 'Mùa Cự Giải (21/6 - 22/7) hoặc diễn ra nhanh chóng trong vòng 1 tháng.', 'assets/cards/the_chariot.jpg') ON DUPLICATE KEY UPDATE `name_vi` = VALUES(`name_vi`), `name_en` = VALUES(`name_en`), `arcana_type` = VALUES(`arcana_type`), `suit_element` = VALUES(`suit_element`), `keywords` = VALUES(`keywords`), `upright_meaning` = VALUES(`upright_meaning`), `reversed_meaning` = VALUES(`reversed_meaning`), `archetype_story` = VALUES(`archetype_story`), `yes_no_result` = VALUES(`yes_no_result`), `yes_no_reason` = VALUES(`yes_no_reason`), `time_prediction` = VALUES(`time_prediction`), `image_path` = VALUES(`image_path`);

-- [9/78] major-8: Strength (VIII. Sức Mạnh Nhu Thắng Cương (Strength))
INSERT INTO `TarotCard` (`card_id`, `name_vi`, `name_en`, `arcana_type`, `suit_element`, `keywords`, `upright_meaning`, `reversed_meaning`, `archetype_story`, `yes_no_result`, `yes_no_reason`, `time_prediction`, `image_path`) VALUES ('major-8', 'VIII. Sức Mạnh Nhu Thắng Cương (Strength)', 'Strength', 'Major', 'Lửa', 'Lòng dũng cảm, Sự dịu dàng, Kiềm chế cảm xúc, Nội lực bền bỉ', 'Chế ngự nỗi sợ và dục vọng bằng lòng trắc ẩn, sự kiên nhẫn và tình yêu thương dịu dàng thay vì bạo lực thô bạo.', 'Nghi ngờ bản thân, yếu lòng trước cám dỗ, bộc phát cơn giận dữ hoặc cảm thấy bất lực.', 'Nguyên mẫu Thuần Hóa Bản Năng (Taming the Beast) và Sức Mạnh Tinh Thần. Người phụ nữ dịu dàng khép miệng sư tử bằng vòng hoa và tình thương, thể hiện triết lý nhu thắng cương, sự kiên nhẫn và lòng trắc ẩn chế ngự dục vọng thô bạo.', 'YES', 'Bạn có đủ nội lực và sự điềm tĩnh để hóa giải khó khăn; hãy dùng lòng kiên nhẫn và sự dịu dàng thay vì áp đặt thô bạo.', 'Mùa Sư Tử (23/7 - 22/8) hoặc khoảng 8 tuần / 2 tháng.', 'assets/cards/strength.jpg') ON DUPLICATE KEY UPDATE `name_vi` = VALUES(`name_vi`), `name_en` = VALUES(`name_en`), `arcana_type` = VALUES(`arcana_type`), `suit_element` = VALUES(`suit_element`), `keywords` = VALUES(`keywords`), `upright_meaning` = VALUES(`upright_meaning`), `reversed_meaning` = VALUES(`reversed_meaning`), `archetype_story` = VALUES(`archetype_story`), `yes_no_result` = VALUES(`yes_no_result`), `yes_no_reason` = VALUES(`yes_no_reason`), `time_prediction` = VALUES(`time_prediction`), `image_path` = VALUES(`image_path`);

-- [10/78] major-9: The Hermit (IX. Ẩn Sĩ (The Hermit))
INSERT INTO `TarotCard` (`card_id`, `name_vi`, `name_en`, `arcana_type`, `suit_element`, `keywords`, `upright_meaning`, `reversed_meaning`, `archetype_story`, `yes_no_result`, `yes_no_reason`, `time_prediction`, `image_path`) VALUES ('major-9', 'IX. Ẩn Sĩ (The Hermit)', 'The Hermit', 'Major', 'Đất', 'Tự vấn lương tâm, Tìm kiếm chân lý, Tách biệt suy ngẫm, Ánh sáng soi đường', 'Thời điểm cần lùi lại một bước, tĩnh tâm soi rọi thế giới nội tâm để tìm ra chân lý và phương hướng thực sự của cuộc đời.', 'Cô lập bản thân thái quá, cô đơn bi quan, từ chối sự giúp đỡ hoặc lạc lối trong định kiến cá nhân.', 'Nguyên mẫu Nhà Thông Thái Đi Tìm Chân Lý (The Wise Hermit). Vị ẩn sĩ đứng một mình trên đỉnh núi tuyết cầm ngọn đèn lồng soi rọi ngôi sao sáu cánh, đại diện cho việc tạm lánh đám đông để tự vấn lương tâm và tìm ra ngọn hải đăng soi sáng bản ngã.', 'MAYBE', 'Hiện tại chưa phải lúc mở rộng ra thế giới bên ngoài; bạn cần khoảng lặng nhìn lại chính mình để thấu suốt bản chất sự việc trước khi quyết định.', 'Mùa Xử Nữ (23/8 - 22/9) hoặc thời gian cần tĩnh lặng từ 1 đến vài tháng.', 'assets/cards/the_hermit.jpg') ON DUPLICATE KEY UPDATE `name_vi` = VALUES(`name_vi`), `name_en` = VALUES(`name_en`), `arcana_type` = VALUES(`arcana_type`), `suit_element` = VALUES(`suit_element`), `keywords` = VALUES(`keywords`), `upright_meaning` = VALUES(`upright_meaning`), `reversed_meaning` = VALUES(`reversed_meaning`), `archetype_story` = VALUES(`archetype_story`), `yes_no_result` = VALUES(`yes_no_result`), `yes_no_reason` = VALUES(`yes_no_reason`), `time_prediction` = VALUES(`time_prediction`), `image_path` = VALUES(`image_path`);

-- [11/78] major-10: Wheel of Fortune (X. Bánh Xe Số Phận (Wheel of Fortune))
INSERT INTO `TarotCard` (`card_id`, `name_vi`, `name_en`, `arcana_type`, `suit_element`, `keywords`, `upright_meaning`, `reversed_meaning`, `archetype_story`, `yes_no_result`, `yes_no_reason`, `time_prediction`, `image_path`) VALUES ('major-10', 'X. Bánh Xe Số Phận (Wheel of Fortune)', 'Wheel of Fortune', 'Major', 'Lửa', 'Vận may bất ngờ, Vòng tuần hoàn, Bước ngoặt định mệnh, Cơ hội mới', 'Bánh xe định mệnh đang xoay về phía bạn, mang theo vận may, cơ hội đổi đời và những biến chuyển tích cực không ngờ.', 'Giai đoạn thăng trầm bất khả kháng, vận xui tạm thời, hoặc sự kháng cự không chịu thích nghi với thời cuộc.', 'Nguyên mẫu Vô Thức Tập Thể và Quy Luật Vô Thường (Samsara). Bánh xe vũ trụ không ngừng luân chuyển giữa bốn sinh vật thần thoại, nhắc nhở con người rằng vạn vật luôn biến dịch; điểm tĩnh tại duy nhất chính là tâm thức bất biến ở trục trung tâm.', 'YES', 'Vận may và bước ngoặt định mệnh đang xoay chuyển theo chiều hướng thuận lợi; hãy nắm bắt thời cơ khi bánh xe đưa bạn lên đỉnh.', 'Bất ngờ, theo bước ngoặt chu kỳ sao Mộc (khoảng 10 ngày hoặc mốc chuyển mùa).', 'assets/cards/the_wheel_of_fortune.jpg') ON DUPLICATE KEY UPDATE `name_vi` = VALUES(`name_vi`), `name_en` = VALUES(`name_en`), `arcana_type` = VALUES(`arcana_type`), `suit_element` = VALUES(`suit_element`), `keywords` = VALUES(`keywords`), `upright_meaning` = VALUES(`upright_meaning`), `reversed_meaning` = VALUES(`reversed_meaning`), `archetype_story` = VALUES(`archetype_story`), `yes_no_result` = VALUES(`yes_no_result`), `yes_no_reason` = VALUES(`yes_no_reason`), `time_prediction` = VALUES(`time_prediction`), `image_path` = VALUES(`image_path`);

-- [12/78] major-11: Justice (XI. Công Lý (Justice))
INSERT INTO `TarotCard` (`card_id`, `name_vi`, `name_en`, `arcana_type`, `suit_element`, `keywords`, `upright_meaning`, `reversed_meaning`, `archetype_story`, `yes_no_result`, `yes_no_reason`, `time_prediction`, `image_path`) VALUES ('major-11', 'XI. Công Lý (Justice)', 'Justice', 'Major', 'Khí', 'Sự công bằng, Chân lý rõ ràng, Luật nhân quả, Trách nhiệm hành vi', 'Mọi việc sẽ được phân xử công minh. Bạn gieo nhân nào sẽ gặt quả nấy; sự thật và lẽ phải sẽ chiến thắng.', 'Bất công, dối trá, thiên vị, hoặc từ chối chịu trách nhiệm về những sai sót của mình.', 'Nguyên mẫu Trật Tự Đạo Đức và Quy Luật Nhân Quả (Karma). Nữ thần cầm thanh kiếm phân định sự thật và chiếc cân cân đo hành vi, thể hiện sự công minh tuyệt đối, tính trách nhiệm và quả ngọt/đắng dựa trên chính những gì bạn đã gieo trồng.', 'MAYBE', 'Kết quả sẽ hoàn toàn công bằng dựa trên những gì bạn đã hành xử và nỗ lực; sự thật và tính chính trực sẽ quyết định đáp án cuối cùng.', 'Mùa Thiên Bình (23/9 - 22/10) hoặc khoảng 11 ngày/tuần.', 'assets/cards/justice.jpg') ON DUPLICATE KEY UPDATE `name_vi` = VALUES(`name_vi`), `name_en` = VALUES(`name_en`), `arcana_type` = VALUES(`arcana_type`), `suit_element` = VALUES(`suit_element`), `keywords` = VALUES(`keywords`), `upright_meaning` = VALUES(`upright_meaning`), `reversed_meaning` = VALUES(`reversed_meaning`), `archetype_story` = VALUES(`archetype_story`), `yes_no_result` = VALUES(`yes_no_result`), `yes_no_reason` = VALUES(`yes_no_reason`), `time_prediction` = VALUES(`time_prediction`), `image_path` = VALUES(`image_path`);

-- [13/78] major-12: The Hanged Man (XII. Người Treo Ngược (The Hanged Man))
INSERT INTO `TarotCard` (`card_id`, `name_vi`, `name_en`, `arcana_type`, `suit_element`, `keywords`, `upright_meaning`, `reversed_meaning`, `archetype_story`, `yes_no_result`, `yes_no_reason`, `time_prediction`, `image_path`) VALUES ('major-12', 'XII. Người Treo Ngược (The Hanged Man)', 'The Hanged Man', 'Major', 'Nước', 'Góc nhìn mới, Hy sinh có chủ đích, Đình trệ để giác ngộ, Buông bỏ kiểm soát', 'Hãy sẵn sàng buông bỏ những kỳ vọng cũ để nhìn nhận thế giới từ góc độ hoàn toàn mới. Sự chậm lại lúc này là cần thiết để trưởng thành.', 'Hy sinh vô ích, chống cự thực tại một cách bướng bỉnh hoặc bị trì hoãn vô thời hạn.', 'Nguyên mẫu Sự Hy Sinh Tự Nguyện và Đổi Góc Nhìn (Surrender & Metanoia). Chàng trai tự nguyện treo ngược chân trên cành cây sự sống với vầng hào quang rạng rỡ, tượng trưng cho sự dừng lại cần thiết để nhìn đời bằng lăng kính hoàn toàn mới.', 'MAYBE', 'Mọi việc đang bị trì hoãn để bạn buông bỏ cái tôi cố chấp; cố gượng ép lúc này sẽ không có kết quả, cần học cách chờ đợi và đổi góc nhìn.', 'Thời gian trì hoãn từ vài tuần đến vài tháng; sự việc diễn ra chậm rãi.', 'assets/cards/the_hanged_man.jpg') ON DUPLICATE KEY UPDATE `name_vi` = VALUES(`name_vi`), `name_en` = VALUES(`name_en`), `arcana_type` = VALUES(`arcana_type`), `suit_element` = VALUES(`suit_element`), `keywords` = VALUES(`keywords`), `upright_meaning` = VALUES(`upright_meaning`), `reversed_meaning` = VALUES(`reversed_meaning`), `archetype_story` = VALUES(`archetype_story`), `yes_no_result` = VALUES(`yes_no_result`), `yes_no_reason` = VALUES(`yes_no_reason`), `time_prediction` = VALUES(`time_prediction`), `image_path` = VALUES(`image_path`);

-- [14/78] major-13: Death (XIII. Chuyển Hóa & Tái Sinh (Death))
INSERT INTO `TarotCard` (`card_id`, `name_vi`, `name_en`, `arcana_type`, `suit_element`, `keywords`, `upright_meaning`, `reversed_meaning`, `archetype_story`, `yes_no_result`, `yes_no_reason`, `time_prediction`, `image_path`) VALUES ('major-13', 'XIII. Chuyển Hóa & Tái Sinh (Death)', 'Death', 'Major', 'Nước', 'Kết thúc chu kỳ cũ, Chuyển hóa mạnh mẽ, Tái sinh từ tro tàn, Buông bỏ dứt khoát', 'Một cánh cửa cũ khép lại để mở ra một khởi đầu mới rực rỡ hơn. Hãy dũng cảm buông bỏ những điều không còn phù hợp để đón nhận sự tái sinh.', 'Sợ hãi thay đổi, níu kéo quá khứ đã tàn lụi, kháng cự quy luật tự nhiên gây đau khổ kéo dài.', 'Nguyên mẫu Sự Tái Sinh và Cái Chết Tâm Lý (Transformation). Kỵ sĩ xương mặc giáp đen cưỡi ngựa trắng bước qua tro tàn hướng về ánh bình minh phía xa, biểu thị sự chấm dứt tất yếu của cái cũ để nhường chỗ cho mầm sống mới đâm chồi.', 'NO', 'Giai đoạn cũ đã đến lúc phải khép lại; đừng cố níu giữ những gì không còn phục vụ cho sự tiến hóa của tâm hồn bạn.', 'Mùa Bọ Cạp (23/10 - 21/11) hoặc thời điểm kết thúc một chu kỳ để bắt đầu cái mới.', 'assets/cards/death.jpg') ON DUPLICATE KEY UPDATE `name_vi` = VALUES(`name_vi`), `name_en` = VALUES(`name_en`), `arcana_type` = VALUES(`arcana_type`), `suit_element` = VALUES(`suit_element`), `keywords` = VALUES(`keywords`), `upright_meaning` = VALUES(`upright_meaning`), `reversed_meaning` = VALUES(`reversed_meaning`), `archetype_story` = VALUES(`archetype_story`), `yes_no_result` = VALUES(`yes_no_result`), `yes_no_reason` = VALUES(`yes_no_reason`), `time_prediction` = VALUES(`time_prediction`), `image_path` = VALUES(`image_path`);

-- [15/78] major-14: Temperance (XIV. Tiết Chế & Hòa Hợp (Temperance))
INSERT INTO `TarotCard` (`card_id`, `name_vi`, `name_en`, `arcana_type`, `suit_element`, `keywords`, `upright_meaning`, `reversed_meaning`, `archetype_story`, `yes_no_result`, `yes_no_reason`, `time_prediction`, `image_path`) VALUES ('major-14', 'XIV. Tiết Chế & Hòa Hợp (Temperance)', 'Temperance', 'Major', 'Lửa', 'Cân bằng hài hòa, Điều độ kiên nhẫn, Dung hợp hoàn hảo, Chữa lành nội tâm', 'Sự dung hòa hoàn hảo giữa các mặt đối lập, giữ tâm thế bình an và kiên nhẫn rót dòng nước sự sống từ từ để tạo nên điều kỳ diệu.', 'Mất cân bằng, nóng nảy cực đoan, xung đột lợi ích hoặc lối sống buông thả quá đà.', 'Nguyên mẫu Giả Kim Thuật Tâm Hồn (Alchemy) và Cân Bằng Năng Lượng. Thiên thần một chân đặt dưới nước, một chân trên đất liền, rót nước qua lại giữa hai chiếc chén mà không làm sánh một giọt, biểu hiện của sự dung hòa, điều tiết và chữa lành vi diệu.', 'YES', 'Sự dung hòa, kiên nhễn và điều độ sẽ mang lại kết quả bình an, bền vững và thuận hòa cho mọi phía.', 'Mùa Nhân Mã (22/11 - 21/12) hoặc cần khoảng thời gian dung hòa từ 1 đến 3 tháng.', 'assets/cards/temperance.jpg') ON DUPLICATE KEY UPDATE `name_vi` = VALUES(`name_vi`), `name_en` = VALUES(`name_en`), `arcana_type` = VALUES(`arcana_type`), `suit_element` = VALUES(`suit_element`), `keywords` = VALUES(`keywords`), `upright_meaning` = VALUES(`upright_meaning`), `reversed_meaning` = VALUES(`reversed_meaning`), `archetype_story` = VALUES(`archetype_story`), `yes_no_result` = VALUES(`yes_no_result`), `yes_no_reason` = VALUES(`yes_no_reason`), `time_prediction` = VALUES(`time_prediction`), `image_path` = VALUES(`image_path`);

-- [16/78] major-15: The Devil (XV. Ác Quỷ (The Devil))
INSERT INTO `TarotCard` (`card_id`, `name_vi`, `name_en`, `arcana_type`, `suit_element`, `keywords`, `upright_meaning`, `reversed_meaning`, `archetype_story`, `yes_no_result`, `yes_no_reason`, `time_prediction`, `image_path`) VALUES ('major-15', 'XV. Ác Quỷ (The Devil)', 'The Devil', 'Major', 'Đất', 'Cám dỗ vật chất, Mê muội ràng buộc, Ảo tưởng phụ thuộc, Bóng tối tâm lý', 'Cảnh báo bạn đang bị trói buộc bởi những dục vọng, thói quen tiêu cực hoặc nỗi sợ hãi do chính tâm trí bạn tạo ra.', 'Thức tỉnh, nhận ra xiềng xích vô hình, dũng cảm cắt đứt mối quan hệ độc hại hoặc vượt qua thói quen xấu.', 'Nguyên mẫu Cái Bóng Tâm Lý (The Shadow) và Xiềng Xích Ảo Tưởng. Cặp đôi bị xích lỏng lẻo dưới chân ác quỷ Baphomet, biểu trưng cho sự lệ thuộc vào dục vọng, nỗi sợ hãi, lòng tham vật chất mà thực chất chỉ là ảo tưởng do tâm trí tự trói buộc.', 'NO', 'Dấu hiệu của sự độc hại, phụ thuộc mù quáng hoặc cám dỗ nguy hiểm; nếu tiếp tục bạn sẽ đánh mất tự do và quyền tự chủ cá nhân.', 'Mùa Ma Kết (22/12 - 19/1) hoặc giai đoạn bế tắc ngắn hạn.', 'assets/cards/the_devil.jpg') ON DUPLICATE KEY UPDATE `name_vi` = VALUES(`name_vi`), `name_en` = VALUES(`name_en`), `arcana_type` = VALUES(`arcana_type`), `suit_element` = VALUES(`suit_element`), `keywords` = VALUES(`keywords`), `upright_meaning` = VALUES(`upright_meaning`), `reversed_meaning` = VALUES(`reversed_meaning`), `archetype_story` = VALUES(`archetype_story`), `yes_no_result` = VALUES(`yes_no_result`), `yes_no_reason` = VALUES(`yes_no_reason`), `time_prediction` = VALUES(`time_prediction`), `image_path` = VALUES(`image_path`);

-- [17/78] major-16: The Tower (XVI. Tòa Tháp Đổ (The Tower))
INSERT INTO `TarotCard` (`card_id`, `name_vi`, `name_en`, `arcana_type`, `suit_element`, `keywords`, `upright_meaning`, `reversed_meaning`, `archetype_story`, `yes_no_result`, `yes_no_reason`, `time_prediction`, `image_path`) VALUES ('major-16', 'XVI. Tòa Tháp Đổ (The Tower)', 'The Tower', 'Major', 'Lửa', 'Sụp đổ bất ngờ, Thức tỉnh đột ngột, Giải thoát khỏi ảo tưởng, Biến cố định mệnh', 'Sét đánh làm sụp đổ những nền móng giả tạo. Dù biến cố có thể gây choáng váng nhưng đó là đòn bẩy cần thiết để giải phóng bạn khỏi sự dối trá.', 'Trì hoãn điều tất yếu phải xảy ra, sợ hãi đối mặt với sự thật, hoặc may mắn thoát khỏi thảm họa trong gang tấc.', 'Nguyên mẫu Sự Sụp Đổ Của Bản Ngã (Ego Collapse) và Sấm Sét Thức Tỉnh. Tia sét đánh sụp đỉnh tháp ngạo mạn, hất tung những ảo tưởng để trả con người về mặt đất chân thực; đau đớn nhưng là sự giải phóng tất yếu khỏi một nhà tù tâm lý.', 'NO', 'Nền tảng hiện tại xây trên ảo tưởng và nguy cơ sụp đổ rất cao; vũ trụ đang buộc bạn thức tỉnh và tái cấu trúc lại từ đầu.', 'Đột ngột như sét đánh, diễn ra tức khắc trong vài ngày tới hoặc mùa sao Hỏa.', 'assets/cards/the_tower.jpg') ON DUPLICATE KEY UPDATE `name_vi` = VALUES(`name_vi`), `name_en` = VALUES(`name_en`), `arcana_type` = VALUES(`arcana_type`), `suit_element` = VALUES(`suit_element`), `keywords` = VALUES(`keywords`), `upright_meaning` = VALUES(`upright_meaning`), `reversed_meaning` = VALUES(`reversed_meaning`), `archetype_story` = VALUES(`archetype_story`), `yes_no_result` = VALUES(`yes_no_result`), `yes_no_reason` = VALUES(`yes_no_reason`), `time_prediction` = VALUES(`time_prediction`), `image_path` = VALUES(`image_path`);

-- [18/78] major-17: The Star (XVII. Ngôi Sao Hy Vọng (The Star))
INSERT INTO `TarotCard` (`card_id`, `name_vi`, `name_en`, `arcana_type`, `suit_element`, `keywords`, `upright_meaning`, `reversed_meaning`, `archetype_story`, `yes_no_result`, `yes_no_reason`, `time_prediction`, `image_path`) VALUES ('major-17', 'XVII. Ngôi Sao Hy Vọng (The Star)', 'The Star', 'Major', 'Khí', 'Hy vọng tái sinh, Niềm tin rạng ngời, Chữa lành tâm hồn, Cảm hứng vô tận', 'Sau cơn giông bão là ánh sao hy vọng dẫn đường. Bình an, lạc quan và cảm hứng tươi mới đang tràn ngập tâm hồn bạn.', 'Mất niềm tin, bi quan thất vọng, cảm thấy cô đơn và không nhìn thấy ánh sáng cuối đường hầm.', 'Nguyên mẫu Hy Vọng và Nguồn Sống Tinh Khiết (The Guiding Star). Người thiếu nữ khỏa thân đổ nước nguồn vào đất và hồ dưới bầu trời đầy sao lấp lánh, tượng trưng cho sự chữa lành sâu sắc sau giông bão, niềm tin vào vũ trụ và vẻ đẹp chân thật.', 'YES', 'Ánh sáng hy vọng và sự bảo trợ tâm linh đang soi rọi con đường bạn đi; hãy giữ vững niềm tin thuần khiết, ước mơ sẽ thành tựu.', 'Mùa Bảo Bình (20/1 - 18/2) hoặc nở rộ sau giai đoạn chữa lành (khoảng 2 - 3 tháng).', 'assets/cards/the_star.jpg') ON DUPLICATE KEY UPDATE `name_vi` = VALUES(`name_vi`), `name_en` = VALUES(`name_en`), `arcana_type` = VALUES(`arcana_type`), `suit_element` = VALUES(`suit_element`), `keywords` = VALUES(`keywords`), `upright_meaning` = VALUES(`upright_meaning`), `reversed_meaning` = VALUES(`reversed_meaning`), `archetype_story` = VALUES(`archetype_story`), `yes_no_result` = VALUES(`yes_no_result`), `yes_no_reason` = VALUES(`yes_no_reason`), `time_prediction` = VALUES(`time_prediction`), `image_path` = VALUES(`image_path`);

-- [19/78] major-18: The Moon (XVIII. Mặt Trăng Huyền Bí (The Moon))
INSERT INTO `TarotCard` (`card_id`, `name_vi`, `name_en`, `arcana_type`, `suit_element`, `keywords`, `upright_meaning`, `reversed_meaning`, `archetype_story`, `yes_no_result`, `yes_no_reason`, `time_prediction`, `image_path`) VALUES ('major-18', 'XVIII. Mặt Trăng Huyền Bí (The Moon)', 'The Moon', 'Major', 'Nước', 'Mơ hồ bất an, Ảo tưởng tiềm thức, Bí mật ẩn giấu, Trực giác nhạy cảm', 'Cảnh báo những điều không rõ ràng, sự nghi ngờ và nỗi sợ vô hình từ tiềm thức. Đừng vội vàng đưa ra quyết định khi sương mù chưa tan.', 'Sự thật dần được đưa ra ánh sáng, bóng tối sợ hãi tan biến, tìm lại sự sáng suốt trong suy nghĩ.', 'Nguyên mẫu Vùng Vô Thức Nguyên Thủy (The Wild Unconscious) và Ảo Ảnh Sợ Hãi. Hai chú chó sói hú dưới ánh trăng mờ ảo cùng con tôm trồi lên từ đầm lầy, đại diện cho những nỗi sợ mơ hồ, ảo tưởng và hành trình vượt qua mê hồn trận của tâm trí.', 'NO', 'Mọi thứ còn chìm trong sương mù ảo giác và sự nghi kỵ; chưa thể nhìn rõ thực tế nên nếu quyết định lúc này rất dễ bị lừa dối hoặc lạc lối.', 'Mùa Song Ngư (19/2 - 20/3) hoặc chu kỳ 1 tháng trăng từ non đến tròn.', 'assets/cards/the_moon.jpg') ON DUPLICATE KEY UPDATE `name_vi` = VALUES(`name_vi`), `name_en` = VALUES(`name_en`), `arcana_type` = VALUES(`arcana_type`), `suit_element` = VALUES(`suit_element`), `keywords` = VALUES(`keywords`), `upright_meaning` = VALUES(`upright_meaning`), `reversed_meaning` = VALUES(`reversed_meaning`), `archetype_story` = VALUES(`archetype_story`), `yes_no_result` = VALUES(`yes_no_result`), `yes_no_reason` = VALUES(`yes_no_reason`), `time_prediction` = VALUES(`time_prediction`), `image_path` = VALUES(`image_path`);

-- [20/78] major-19: The Sun (XIX. Mặt Trời Rực Rỡ (The Sun))
INSERT INTO `TarotCard` (`card_id`, `name_vi`, `name_en`, `arcana_type`, `suit_element`, `keywords`, `upright_meaning`, `reversed_meaning`, `archetype_story`, `yes_no_result`, `yes_no_reason`, `time_prediction`, `image_path`) VALUES ('major-19', 'XIX. Mặt Trời Rực Rỡ (The Sun)', 'The Sun', 'Major', 'Lửa', 'Thành công vang dội, Hạnh phúc ấm áp, Năng lượng rạng ngời, Sự thật tỏ tường', 'Lá bài may mắn bậc nhất Tarot! Báo hiệu niềm vui tột cùng, sức sống dồi dào, thành công rực rỡ và ánh hào quang chiến thắng.', 'Niềm vui bị trì hoãn tạm thời, sự lạc quan thái quá hoặc kiêu ngạo dẫn đến sơ suất.', 'Nguyên mẫu Sự Tỏa Sáng Toàn Bích (The Conscious Self) và Hạnh Phúc Thuần Khiết. Đứa trẻ cưỡi ngựa trắng dưới ánh mặt trời rực rỡ và những bông hướng dương nở rộ, biểu tượng của sự hợp nhất hoàn hảo giữa bản ngã và vũ trụ, thành công viên mãn.', 'YES', 'Năng lượng rực rỡ, may mắn và thành công trọn vẹn; mọi bóng tối hoài nghi đều bị xua tan bởi niềm vui và chân lý sáng ngời.', 'Mùa hè rực rỡ, buổi trưa đầy nắng, hoặc diễn ra viên mãn trong vòng 1 tháng.', 'assets/cards/the_sun.jpg') ON DUPLICATE KEY UPDATE `name_vi` = VALUES(`name_vi`), `name_en` = VALUES(`name_en`), `arcana_type` = VALUES(`arcana_type`), `suit_element` = VALUES(`suit_element`), `keywords` = VALUES(`keywords`), `upright_meaning` = VALUES(`upright_meaning`), `reversed_meaning` = VALUES(`reversed_meaning`), `archetype_story` = VALUES(`archetype_story`), `yes_no_result` = VALUES(`yes_no_result`), `yes_no_reason` = VALUES(`yes_no_reason`), `time_prediction` = VALUES(`time_prediction`), `image_path` = VALUES(`image_path`);

-- [21/78] major-20: Judgement (XX. Phán Xét & Thức Tỉnh (Judgement))
INSERT INTO `TarotCard` (`card_id`, `name_vi`, `name_en`, `arcana_type`, `suit_element`, `keywords`, `upright_meaning`, `reversed_meaning`, `archetype_story`, `yes_no_result`, `yes_no_reason`, `time_prediction`, `image_path`) VALUES ('major-20', 'XX. Phán Xét & Thức Tỉnh (Judgement)', 'Judgement', 'Major', 'Lửa', 'Tiếng gọi định mệnh, Thức tỉnh tâm linh, Đánh giá lại quá khứ, Sự tha thứ', 'Tiếng kèn thiên sứ vang lên kêu gọi bạn thức tỉnh. Đã đến lúc đánh giá lại chặng đường đã qua để bước lên một tầm cao mới của nhận thức.', 'Tự phán xét bản thân quá khắc nghiệt, do dự chần chừ không dám nghe theo tiếng gọi định mệnh, tiếc nuối quá khứ.', 'Nguyên mẫu Sự Phục Sinh và Thức Tỉnh Lương Tri (Resurrection). Tiếng kèn của thiên thần thức tỉnh những linh hồn trỗi dậy từ nấm mồ, đại diện cho việc rũ bỏ quá khứ, tha thứ cho bản thân và bước vào một tầm mức tâm thức cao hơn.', 'YES', 'Thời điểm chín muồi để đưa ra quyết định bước ngoặt; hãy lắng nghe tiếng gọi chân thật của lương tri và tự tin tái sinh.', 'Thời điểm quyết định bước ngoặt, không thể trì hoãn; diễn ra trong vòng vài tuần.', 'assets/cards/judgement.jpg') ON DUPLICATE KEY UPDATE `name_vi` = VALUES(`name_vi`), `name_en` = VALUES(`name_en`), `arcana_type` = VALUES(`arcana_type`), `suit_element` = VALUES(`suit_element`), `keywords` = VALUES(`keywords`), `upright_meaning` = VALUES(`upright_meaning`), `reversed_meaning` = VALUES(`reversed_meaning`), `archetype_story` = VALUES(`archetype_story`), `yes_no_result` = VALUES(`yes_no_result`), `yes_no_reason` = VALUES(`yes_no_reason`), `time_prediction` = VALUES(`time_prediction`), `image_path` = VALUES(`image_path`);

-- [22/78] major-21: The World (XXI. Thế Giới Viên Mãn (The World))
INSERT INTO `TarotCard` (`card_id`, `name_vi`, `name_en`, `arcana_type`, `suit_element`, `keywords`, `upright_meaning`, `reversed_meaning`, `archetype_story`, `yes_no_result`, `yes_no_reason`, `time_prediction`, `image_path`) VALUES ('major-21', 'XXI. Thế Giới Viên Mãn (The World)', 'The World', 'Major', 'Đất', 'Viên mãn trọn vẹn, Hoàn thành mục tiêu, Hòa hợp vũ trụ, Khởi đầu chu kỳ mới', 'Đỉnh cao của hành trình Tarot! Mọi nỗ lực của bạn đã đơm hoa kết trái viên mãn, sự trọn vẹn và tự do tuyệt đối trong tâm hồn.', 'Gần chạm tới đích nhưng còn dang dở một bước cuối, thiếu sự kiên trì để hoàn tất chặng cuối.', 'Nguyên mẫu Sự Toàn Vẹn Tự Thân (Individuation / Mandala Vũ Trụ). Người nhảy múa trong vòng nguyệt quế giữa bốn vị thần bảo hộ, tượng trưng cho sự hoàn tất vẻ vang một chu kỳ tiến hóa tâm linh, hợp nhất trọn vẹn với dòng chảy sự sống.', 'YES', 'Mọi nỗ lực đã đi đến đỉnh cao viên mãn; bạn đang chạm tay vào sự trọn vẹn, mở ra một chương đời mới đầy tự do và thành tựu.', 'Kết thúc một chu kỳ lớn (cuối năm hoặc sau khi hoàn thành chu kỳ 4 mùa).', 'assets/cards/the_world.jpg') ON DUPLICATE KEY UPDATE `name_vi` = VALUES(`name_vi`), `name_en` = VALUES(`name_en`), `arcana_type` = VALUES(`arcana_type`), `suit_element` = VALUES(`suit_element`), `keywords` = VALUES(`keywords`), `upright_meaning` = VALUES(`upright_meaning`), `reversed_meaning` = VALUES(`reversed_meaning`), `archetype_story` = VALUES(`archetype_story`), `yes_no_result` = VALUES(`yes_no_result`), `yes_no_reason` = VALUES(`yes_no_reason`), `time_prediction` = VALUES(`time_prediction`), `image_path` = VALUES(`image_path`);

-- [23/78] wands-1: Ace of Wands (Ace of Wands (Ách Gậy))
INSERT INTO `TarotCard` (`card_id`, `name_vi`, `name_en`, `arcana_type`, `suit_element`, `keywords`, `upright_meaning`, `reversed_meaning`, `archetype_story`, `yes_no_result`, `yes_no_reason`, `time_prediction`, `image_path`) VALUES ('wands-1', 'Ace of Wands (Ách Gậy)', 'Ace of Wands', 'Minor', 'Lửa', 'Tia lửa cảm hứng, Khởi đầu rực cháy, Năng lượng dồi dào, Ý chí quyết tâm', 'Một luồng cảm hứng mới thổi bùng ngọn lửa sáng tạo và thôi thúc bạn bắt tay vào hành động ngay lập tức.', 'Thiếu động lực, ý tưởng bị đình trệ, sự nhiệt tình ban đầu nguội lạnh nhanh chóng.', 'Hạt mầm ý chí và ngọn lửa sáng tạo nguyên khôi. Bàn tay vũ trụ trao cây gậy nảy lộc giữa trời mây, biểu tượng cho nguồn cảm hứng bộc phát và sự can đảm khai mở hành trình mới.', 'YES', 'Ngọn lửa nhiệt huyết và cơ hội mới đang bùng cháy mạnh mẽ; hành động ngay sẽ gặt hái kết quả rực rỡ.', '1 ngày hoặc mùa xuân (Bạch Dương).', 'assets/cards/wands_01.jpg') ON DUPLICATE KEY UPDATE `name_vi` = VALUES(`name_vi`), `name_en` = VALUES(`name_en`), `arcana_type` = VALUES(`arcana_type`), `suit_element` = VALUES(`suit_element`), `keywords` = VALUES(`keywords`), `upright_meaning` = VALUES(`upright_meaning`), `reversed_meaning` = VALUES(`reversed_meaning`), `archetype_story` = VALUES(`archetype_story`), `yes_no_result` = VALUES(`yes_no_result`), `yes_no_reason` = VALUES(`yes_no_reason`), `time_prediction` = VALUES(`time_prediction`), `image_path` = VALUES(`image_path`);

-- [24/78] wands-2: Two of Wands (Two of Wands (Hai Gậy))
INSERT INTO `TarotCard` (`card_id`, `name_vi`, `name_en`, `arcana_type`, `suit_element`, `keywords`, `upright_meaning`, `reversed_meaning`, `archetype_story`, `yes_no_result`, `yes_no_reason`, `time_prediction`, `image_path`) VALUES ('wands-2', 'Two of Wands (Hai Gậy)', 'Two of Wands', 'Minor', 'Lửa', 'Lên kế hoạch tương lai, Tầm nhìn xa, Bước ra thế giới, Quyết định bước ngoặt', 'Bạn đã có nền tảng vững chắc và đang đứng trên đỉnh cao nhìn ra thế giới rộng lớn để vạch ra chiến lược đường dài.', 'Sợ hãi rủi ro khi bước ra khỏi vùng an toàn, kế hoạch thiếu tính thực tế.', 'Người chỉ huy đứng trên lâu đài cầm quả địa cầu ngắm nhìn đại dương xa xăm. Sự cân nhắc giữa vùng an toàn hiện tại và khát vọng chinh phục thế giới rộng lớn hơn.', 'MAYBE', 'Bạn đang đứng trước ngã rẽ lựa chọn mở rộng tầm nhìn; cần lập kế hoạch cụ thể trước khi dấn thân.', '2 ngày hoặc đầu mùa xuân (khoảng 21/3 - 30/3).', 'assets/cards/wands_02.jpg') ON DUPLICATE KEY UPDATE `name_vi` = VALUES(`name_vi`), `name_en` = VALUES(`name_en`), `arcana_type` = VALUES(`arcana_type`), `suit_element` = VALUES(`suit_element`), `keywords` = VALUES(`keywords`), `upright_meaning` = VALUES(`upright_meaning`), `reversed_meaning` = VALUES(`reversed_meaning`), `archetype_story` = VALUES(`archetype_story`), `yes_no_result` = VALUES(`yes_no_result`), `yes_no_reason` = VALUES(`yes_no_reason`), `time_prediction` = VALUES(`time_prediction`), `image_path` = VALUES(`image_path`);

-- [25/78] wands-3: Three of Wands (Three of Wands (Ba Gậy))
INSERT INTO `TarotCard` (`card_id`, `name_vi`, `name_en`, `arcana_type`, `suit_element`, `keywords`, `upright_meaning`, `reversed_meaning`, `archetype_story`, `yes_no_result`, `yes_no_reason`, `time_prediction`, `image_path`) VALUES ('wands-3', 'Three of Wands (Ba Gậy)', 'Three of Wands', 'Minor', 'Lửa', 'Mở rộng cơ hội, Tầm nhìn phát triển, Đón tàu về bến, Khám phá chân trời mới', 'Những hạt mầm bạn gieo trồng đang bắt đầu đơm hoa. Hãy sẵn sàng đón nhận những chuyến tàu chở đầy tài lộc và cơ hội trở về.', 'Sự chậm trễ trong các kế hoạch, thất vọng vì kết quả đến chậm hơn dự tính.', 'Lữ khách đứng trên vách đá ngắm nhìn đoàn thuyền chở hàng xuôi gió ra khơi. Nỗ lực bước đầu đã được phóng thích và bắt đầu mở ra chân trời cơ hội mới.', 'YES', 'Những hạt mầm bạn gieo và đoàn thuyền bạn gửi đi đang trên đường mang lại tin vui và thành quả mở rộng.', '3 ngày hoặc giữa mùa xuân (khoảng 31/3 - 10/4).', 'assets/cards/wands_03.jpg') ON DUPLICATE KEY UPDATE `name_vi` = VALUES(`name_vi`), `name_en` = VALUES(`name_en`), `arcana_type` = VALUES(`arcana_type`), `suit_element` = VALUES(`suit_element`), `keywords` = VALUES(`keywords`), `upright_meaning` = VALUES(`upright_meaning`), `reversed_meaning` = VALUES(`reversed_meaning`), `archetype_story` = VALUES(`archetype_story`), `yes_no_result` = VALUES(`yes_no_result`), `yes_no_reason` = VALUES(`yes_no_reason`), `time_prediction` = VALUES(`time_prediction`), `image_path` = VALUES(`image_path`);

-- [26/78] wands-4: Four of Wands (Four of Wands (Bốn Gậy))
INSERT INTO `TarotCard` (`card_id`, `name_vi`, `name_en`, `arcana_type`, `suit_element`, `keywords`, `upright_meaning`, `reversed_meaning`, `archetype_story`, `yes_no_result`, `yes_no_reason`, `time_prediction`, `image_path`) VALUES ('wands-4', 'Four of Wands (Bốn Gậy)', 'Four of Wands', 'Minor', 'Lửa', 'Ăn mừng chiến thắng, Gia đình sum vầy, Tổ ấm bình yên, Cột mốc thành công', 'Không khí lễ hội hân hoan, sum họp gia đình, kỷ niệm ngày vui trọng đại như đám cưới, tân gia hoặc hoàn thành một dự án lớn.', 'Không khí gia đình có chút bất hòa, bữa tiệc bị gián đoạn hoặc cảm giác lạc lõng giữa đám đông.', 'Cổng hoa bốn gậy rực rỡ chào đón đôi uyên ương trong ngày hội mùa màng. Đại diện cho niềm vui sum vầy, sự ổn định gia đình và cột mốc thành công xứng đáng được tán dương.', 'YES', 'Nền tảng vững chắc, niềm vui sum vầy và thành công xứng đáng được chúc mừng; mọi sự bình an thuận lợi.', '4 ngày hoặc mùa xuân hoa nở rộ (khoảng 11/4 - 20/4).', 'assets/cards/wands_04.jpg') ON DUPLICATE KEY UPDATE `name_vi` = VALUES(`name_vi`), `name_en` = VALUES(`name_en`), `arcana_type` = VALUES(`arcana_type`), `suit_element` = VALUES(`suit_element`), `keywords` = VALUES(`keywords`), `upright_meaning` = VALUES(`upright_meaning`), `reversed_meaning` = VALUES(`reversed_meaning`), `archetype_story` = VALUES(`archetype_story`), `yes_no_result` = VALUES(`yes_no_result`), `yes_no_reason` = VALUES(`yes_no_reason`), `time_prediction` = VALUES(`time_prediction`), `image_path` = VALUES(`image_path`);

-- [27/78] wands-5: Five of Wands (Five of Wands (Năm Gậy))
INSERT INTO `TarotCard` (`card_id`, `name_vi`, `name_en`, `arcana_type`, `suit_element`, `keywords`, `upright_meaning`, `reversed_meaning`, `archetype_story`, `yes_no_result`, `yes_no_reason`, `time_prediction`, `image_path`) VALUES ('wands-5', 'Five of Wands (Năm Gậy)', 'Five of Wands', 'Minor', 'Lửa', 'Cạnh tranh gay gắt, Xung đột ý kiến, Hỗn loạn thử thách, Đấu tranh khẳng định mình', 'Môi trường cạnh tranh sôi nổi, nhiều ý kiến trái chiều tranh luận nảy lửa đòi hỏi bạn phải chứng tỏ bản lĩnh và sự linh hoạt.', 'Tránh né xung đột để tìm kiếm thỏa hiệp, hoặc mệt mỏi vì những cuộc tranh cãi vặt vãnh vô bổ.', 'Năm chàng thanh niên vung gậy tranh đấu lẫn nhau giữa bãi đất trống. Đại diện cho sự cạnh tranh gay gắt, xung đột quan điểm và sự phân tán năng lượng do thiếu tổ chức.', 'NO', 'Năng lượng đang bị tiêu hao bởi tranh cãi và đấu đá nội bộ; cần tìm kiếm tiếng nói chung thay vì tiếp tục đối đầu.', '5 ngày hoặc mùa hè (Sư Tử - khoảng 22/7 - 1/8).', 'assets/cards/wands_05.jpg') ON DUPLICATE KEY UPDATE `name_vi` = VALUES(`name_vi`), `name_en` = VALUES(`name_en`), `arcana_type` = VALUES(`arcana_type`), `suit_element` = VALUES(`suit_element`), `keywords` = VALUES(`keywords`), `upright_meaning` = VALUES(`upright_meaning`), `reversed_meaning` = VALUES(`reversed_meaning`), `archetype_story` = VALUES(`archetype_story`), `yes_no_result` = VALUES(`yes_no_result`), `yes_no_reason` = VALUES(`yes_no_reason`), `time_prediction` = VALUES(`time_prediction`), `image_path` = VALUES(`image_path`);

-- [28/78] wands-6: Six of Wands (Six of Wands (Sáu Gậy))
INSERT INTO `TarotCard` (`card_id`, `name_vi`, `name_en`, `arcana_type`, `suit_element`, `keywords`, `upright_meaning`, `reversed_meaning`, `archetype_story`, `yes_no_result`, `yes_no_reason`, `time_prediction`, `image_path`) VALUES ('wands-6', 'Six of Wands (Sáu Gậy)', 'Six of Wands', 'Minor', 'Lửa', 'Vinh quang khải hoàn, Được công nhận, Tự hào dẫn đầu, Chiến thắng vang dội', 'Bạn cưỡi bạch mã trở về trong tiếng reo hò chúc mừng. Những nỗ lực phi thường của bạn đã được đền đáp bằng sự ngưỡng mộ của mọi người.', 'Tự cao tự đại, danh tiếng bị tổn hại, hoặc chiến thắng bị cướp công trắng trợn.', 'Người chiến binh đội vòng nguyệt quế cưỡi ngựa trắng diễu hành giữa tiếng reo hò của đám đông. Biểu tượng của vinh quang chiến thắng và sự công nhận từ cộng đồng.', 'YES', 'Sự công nhận vẻ vang, chiến thắng và sự ngưỡng mộ từ cộng đồng dành cho bạn; tự tin tiến bước.', '6 ngày hoặc giữa mùa hè (khoảng 2/8 - 11/8).', 'assets/cards/wands_06.jpg') ON DUPLICATE KEY UPDATE `name_vi` = VALUES(`name_vi`), `name_en` = VALUES(`name_en`), `arcana_type` = VALUES(`arcana_type`), `suit_element` = VALUES(`suit_element`), `keywords` = VALUES(`keywords`), `upright_meaning` = VALUES(`upright_meaning`), `reversed_meaning` = VALUES(`reversed_meaning`), `archetype_story` = VALUES(`archetype_story`), `yes_no_result` = VALUES(`yes_no_result`), `yes_no_reason` = VALUES(`yes_no_reason`), `time_prediction` = VALUES(`time_prediction`), `image_path` = VALUES(`image_path`);

-- [29/78] wands-7: Seven of Wands (Seven of Wands (Bảy Gậy))
INSERT INTO `TarotCard` (`card_id`, `name_vi`, `name_en`, `arcana_type`, `suit_element`, `keywords`, `upright_meaning`, `reversed_meaning`, `archetype_story`, `yes_no_result`, `yes_no_reason`, `time_prediction`, `image_path`) VALUES ('wands-7', 'Seven of Wands (Bảy Gậy)', 'Seven of Wands', 'Minor', 'Lửa', 'Bảo vệ lập trường, Kiên cường kháng cự, Vững vàng vị thế, Đối mặt áp lực', 'Bạn đang đứng ở vị thế cao hơn và kiên quyết bảo vệ thành quả của mình trước sự công kích của nhiều phía. Đừng lùi bước!', 'Quá tải vì bị tấn công từ mọi hướng, mệt mỏi muốn buông xuôi bỏ cuộc.', 'Chiến sĩ kiên cường đứng trên đỉnh đồi cao chống lại sáu chiếc gậy nhắm vào mình từ bên dưới. Biểu thị bản lĩnh giữ vững lập trường và lợi thế địa hình trước áp lực bủa vây.', 'YES', 'Dù bị bao vây thử thách nhưng vị thế phòng thủ kiên cường của bạn sẽ giúp bạn giữ vững thắng lợi cuối cùng.', '7 ngày hoặc cuối mùa hè (khoảng 12/8 - 22/8).', 'assets/cards/wands_07.jpg') ON DUPLICATE KEY UPDATE `name_vi` = VALUES(`name_vi`), `name_en` = VALUES(`name_en`), `arcana_type` = VALUES(`arcana_type`), `suit_element` = VALUES(`suit_element`), `keywords` = VALUES(`keywords`), `upright_meaning` = VALUES(`upright_meaning`), `reversed_meaning` = VALUES(`reversed_meaning`), `archetype_story` = VALUES(`archetype_story`), `yes_no_result` = VALUES(`yes_no_result`), `yes_no_reason` = VALUES(`yes_no_reason`), `time_prediction` = VALUES(`time_prediction`), `image_path` = VALUES(`image_path`);

-- [30/78] wands-8: Eight of Wands (Eight of Wands (Tám Gậy))
INSERT INTO `TarotCard` (`card_id`, `name_vi`, `name_en`, `arcana_type`, `suit_element`, `keywords`, `upright_meaning`, `reversed_meaning`, `archetype_story`, `yes_no_result`, `yes_no_reason`, `time_prediction`, `image_path`) VALUES ('wands-8', 'Eight of Wands (Tám Gậy)', 'Eight of Wands', 'Minor', 'Lửa', 'Tốc độ thần tốc, Tin tức bay tới, Di chuyển nhanh, Hành động dứt khoát', 'Các sự kiện diễn ra với tốc độ chóng mặt! Tin tức quan trọng đang bay tới, các rào cản được dỡ bỏ và bạn cần hành động ngay.', 'Sự chậm trễ gây bức xúc, thông tin hỗn loạn, hoặc hành động quá hấp tấp gây hỏng việc.', 'Tám cành gậy lao vun vút trên bầu trời thanh bình hướng về mặt đất màu mỡ. Tốc độ chuyển dịch cực nhanh, các sự kiện dồn dập đến và không còn trở ngại cản bước.', 'YES', 'Tốc độ diễn tiến thần tốc, tin tức bất ngờ bay đến tháo gỡ mọi tắc nghẽn và đưa sự việc về đích.', 'Rất nhanh trong 1 - 2 ngày tới, hoặc mùa Nhân Mã (khoảng 23/11 - 2/12).', 'assets/cards/wands_08.jpg') ON DUPLICATE KEY UPDATE `name_vi` = VALUES(`name_vi`), `name_en` = VALUES(`name_en`), `arcana_type` = VALUES(`arcana_type`), `suit_element` = VALUES(`suit_element`), `keywords` = VALUES(`keywords`), `upright_meaning` = VALUES(`upright_meaning`), `reversed_meaning` = VALUES(`reversed_meaning`), `archetype_story` = VALUES(`archetype_story`), `yes_no_result` = VALUES(`yes_no_result`), `yes_no_reason` = VALUES(`yes_no_reason`), `time_prediction` = VALUES(`time_prediction`), `image_path` = VALUES(`image_path`);

-- [31/78] wands-9: Nine of Wands (Nine of Wands (Chín Gậy))
INSERT INTO `TarotCard` (`card_id`, `name_vi`, `name_en`, `arcana_type`, `suit_element`, `keywords`, `upright_meaning`, `reversed_meaning`, `archetype_story`, `yes_no_result`, `yes_no_reason`, `time_prediction`, `image_path`) VALUES ('wands-9', 'Nine of Wands (Chín Gậy)', 'Nine of Wands', 'Minor', 'Lửa', 'Kiên cường chặng cuối, Phòng thủ cảnh giác, Bền bỉ chịu đựng, Sắp cán đích', 'Dù cơ thể mang nhiều vết thương sau những trận chiến ác liệt, bạn vẫn kiên cường đứng vững canh gác. Chỉ còn một thử thách cuối cùng!', 'Kiệt sức, đa nghi quá mức, phòng thủ tiêu cực khiến bản thân luôn sống trong sợ hãi.', 'Người lính băng bó vết thương trên trán nhưng ánh mắt vẫn cảnh giác tựa vào cọc gậy phòng thủ cuối cùng. Sức chịu đựng phi thường và tinh thần kiên cường ở chặng cuối gian nan.', 'MAYBE', 'Bạn đã kiệt sức sau chặng đường dài; chỉ cần phòng thủ kiên trì nốt bước cuối cùng, đừng vội bỏ cuộc.', '9 ngày hoặc giữa mùa Nhân Mã (khoảng 3/12 - 12/12).', 'assets/cards/wands_09.jpg') ON DUPLICATE KEY UPDATE `name_vi` = VALUES(`name_vi`), `name_en` = VALUES(`name_en`), `arcana_type` = VALUES(`arcana_type`), `suit_element` = VALUES(`suit_element`), `keywords` = VALUES(`keywords`), `upright_meaning` = VALUES(`upright_meaning`), `reversed_meaning` = VALUES(`reversed_meaning`), `archetype_story` = VALUES(`archetype_story`), `yes_no_result` = VALUES(`yes_no_result`), `yes_no_reason` = VALUES(`yes_no_reason`), `time_prediction` = VALUES(`time_prediction`), `image_path` = VALUES(`image_path`);

-- [32/78] wands-10: Ten of Wands (Ten of Wands (Mười Gậy))
INSERT INTO `TarotCard` (`card_id`, `name_vi`, `name_en`, `arcana_type`, `suit_element`, `keywords`, `upright_meaning`, `reversed_meaning`, `archetype_story`, `yes_no_result`, `yes_no_reason`, `time_prediction`, `image_path`) VALUES ('wands-10', 'Ten of Wands (Mười Gậy)', 'Ten of Wands', 'Minor', 'Lửa', 'Gánh nặng quá tải, Trách nhiệm đè nặng, Cố gắng kiệt cùng, Cần san sẻ', 'Bạn đang ôm đồm quá nhiều việc cùng lúc và lưng còng xuống vì gánh nặng. Dù sắp tới đích, bạn cần học cách san sẻ bớt công việc.', 'Buông bỏ bớt gánh nặng không cần thiết, hoặc sụp đổ vì không thể gánh vác thêm được nữa.', 'Người đàn ông còng lưng ôm bó mười cây gậy nặng trĩu tiến về ngôi làng phía trước. Đại diện cho gánh nặng trách nhiệm quá tải, sự ôm đồm và nguy cơ kiệt sức do không biết buông bỏ.', 'NO', 'Gánh nặng quá sức chịu đựng; cần học cách buông bỏ bớt trách nhiệm và chia sẻ với người khác.', '10 ngày hoặc cuối mùa Nhân Mã (khoảng 13/12 - 21/12).', 'assets/cards/wands_10.jpg') ON DUPLICATE KEY UPDATE `name_vi` = VALUES(`name_vi`), `name_en` = VALUES(`name_en`), `arcana_type` = VALUES(`arcana_type`), `suit_element` = VALUES(`suit_element`), `keywords` = VALUES(`keywords`), `upright_meaning` = VALUES(`upright_meaning`), `reversed_meaning` = VALUES(`reversed_meaning`), `archetype_story` = VALUES(`archetype_story`), `yes_no_result` = VALUES(`yes_no_result`), `yes_no_reason` = VALUES(`yes_no_reason`), `time_prediction` = VALUES(`time_prediction`), `image_path` = VALUES(`image_path`);

-- [33/78] wands-11: Page of Wands (Page of Wands (Tiểu Đồng Gậy))
INSERT INTO `TarotCard` (`card_id`, `name_vi`, `name_en`, `arcana_type`, `suit_element`, `keywords`, `upright_meaning`, `reversed_meaning`, `archetype_story`, `yes_no_result`, `yes_no_reason`, `time_prediction`, `image_path`) VALUES ('wands-11', 'Page of Wands (Tiểu Đồng Gậy)', 'Page of Wands', 'Minor', 'Lửa', 'Nhiệt huyết trẻ trung, Tin tức hào hứng, Khám phá thế giới, Tinh thần học hỏi', 'Một người trẻ tràn đầy năng lượng hoặc một tin tức thú vị kích thích sự tò mò và khát khao trải nghiệm của bạn.', 'Nông nổi, thiếu kiên nhẫn, thích thể hiện nhưng mau chán, tin tức gây thất vọng.', 'Chàng trai trẻ đứng giữa sa mạc chăm chú ngắm nhìn mầm chồi xanh biếc nảy nở trên đầu ngọn gậy. Tinh thần phiêu lưu, khát khao học hỏi và đón nhận nguồn cảm hứng mới.', 'YES', 'Tinh thần khám phá non trẻ và tin tức hào hứng đang truyền cảm hứng cho bạn bắt đầu.', 'Vài ngày tới hoặc giai đoạn bắt đầu một dự án mới (mùa Lửa).', 'assets/cards/wands_11.jpg') ON DUPLICATE KEY UPDATE `name_vi` = VALUES(`name_vi`), `name_en` = VALUES(`name_en`), `arcana_type` = VALUES(`arcana_type`), `suit_element` = VALUES(`suit_element`), `keywords` = VALUES(`keywords`), `upright_meaning` = VALUES(`upright_meaning`), `reversed_meaning` = VALUES(`reversed_meaning`), `archetype_story` = VALUES(`archetype_story`), `yes_no_result` = VALUES(`yes_no_result`), `yes_no_reason` = VALUES(`yes_no_reason`), `time_prediction` = VALUES(`time_prediction`), `image_path` = VALUES(`image_path`);

-- [34/78] wands-12: Knight of Wands (Knight of Wands (Hiệp Sĩ Gậy))
INSERT INTO `TarotCard` (`card_id`, `name_vi`, `name_en`, `arcana_type`, `suit_element`, `keywords`, `upright_meaning`, `reversed_meaning`, `archetype_story`, `yes_no_result`, `yes_no_reason`, `time_prediction`, `image_path`) VALUES ('wands-12', 'Knight of Wands (Hiệp Sĩ Gậy)', 'Knight of Wands', 'Minor', 'Lửa', 'Hành động táo bạo, Đam mê cuồng nhiệt, Phiêu lưu mạo hiểm, Xông xáo dũng mãnh', 'Kỵ sĩ giục ngựa phi nước đại lao về phía trước với ngọn lửa nhiệt huyết. Không gì có thể ngăn cản bước chân chinh phục của bạn!', 'Hấp tấp liều lĩnh, dễ nổi nóng, hành động bộc phát thiếu suy nghĩ dẫn đến hậu quả tai hại.', 'Kỵ sĩ giáp vàng cưỡi ngựa chiến phi nước đại giữa sa mạc rực lửa. Đại diện cho sự bùng nổ nhiệt huyết, hành động quyết liệt không chút sợ hãi và tính bộc phát mạnh mẽ.', 'YES', 'Hành động thần tốc và lòng quả cảm đưa bạn lao nhanh về phía trước; đừng do dự.', 'Diễn ra cực nhanh trong vài ngày hoặc giữa mùa Lửa.', 'assets/cards/wands_12.jpg') ON DUPLICATE KEY UPDATE `name_vi` = VALUES(`name_vi`), `name_en` = VALUES(`name_en`), `arcana_type` = VALUES(`arcana_type`), `suit_element` = VALUES(`suit_element`), `keywords` = VALUES(`keywords`), `upright_meaning` = VALUES(`upright_meaning`), `reversed_meaning` = VALUES(`reversed_meaning`), `archetype_story` = VALUES(`archetype_story`), `yes_no_result` = VALUES(`yes_no_result`), `yes_no_reason` = VALUES(`yes_no_reason`), `time_prediction` = VALUES(`time_prediction`), `image_path` = VALUES(`image_path`);

-- [35/78] wands-13: Queen of Wands (Queen of Wands (Hoàng Hậu Gậy))
INSERT INTO `TarotCard` (`card_id`, `name_vi`, `name_en`, `arcana_type`, `suit_element`, `keywords`, `upright_meaning`, `reversed_meaning`, `archetype_story`, `yes_no_result`, `yes_no_reason`, `time_prediction`, `image_path`) VALUES ('wands-13', 'Queen of Wands (Hoàng Hậu Gậy)', 'Queen of Wands', 'Minor', 'Lửa', 'Tự tin quyến rũ, Năng lượng ấm áp, Độc lập bản lĩnh, Truyền cảm hứng', 'Một người phụ nữ rạng rỡ, tự tin, phóng khoáng và luôn là tâm điểm thu hút mọi ánh nhìn bằng sự ấm áp và tài năng lãnh đạo.', 'Ghen tị, thao túng người khác bằng sự drama, đòi hỏi sự chú ý thái quá.', 'Hoàng hậu ngồi trên ngai vàng khắc hoa hướng dương và sư tử, tay cầm hoa hướng dương và chú mèo đen bên cạnh. Biểu tượng của sự ấm áp, tự tin, sức quyến rũ và năng lượng tích cực.', 'YES', 'Sức hút tự tin, sự ấm áp và bản lĩnh giúp bạn làm chủ hoàn toàn tình thế và truyền cảm hứng cho mọi người.', 'Khoảng 1 - 2 tuần hoặc mùa xuân ấm áp.', 'assets/cards/wands_13.jpg') ON DUPLICATE KEY UPDATE `name_vi` = VALUES(`name_vi`), `name_en` = VALUES(`name_en`), `arcana_type` = VALUES(`arcana_type`), `suit_element` = VALUES(`suit_element`), `keywords` = VALUES(`keywords`), `upright_meaning` = VALUES(`upright_meaning`), `reversed_meaning` = VALUES(`reversed_meaning`), `archetype_story` = VALUES(`archetype_story`), `yes_no_result` = VALUES(`yes_no_result`), `yes_no_reason` = VALUES(`yes_no_reason`), `time_prediction` = VALUES(`time_prediction`), `image_path` = VALUES(`image_path`);

-- [36/78] wands-14: King of Wands (King of Wands (Vua Gậy))
INSERT INTO `TarotCard` (`card_id`, `name_vi`, `name_en`, `arcana_type`, `suit_element`, `keywords`, `upright_meaning`, `reversed_meaning`, `archetype_story`, `yes_no_result`, `yes_no_reason`, `time_prediction`, `image_path`) VALUES ('wands-14', 'King of Wands (Vua Gậy)', 'King of Wands', 'Minor', 'Lửa', 'Nhà lãnh đạo có tầm nhìn, Ý chí sắt đá, Hùng tâm tráng chí, Khởi xướng vĩ đại', 'Bậc minh quân với tầm nhìn chiến lược vĩ đại, ý chí kiên định và khả năng biến những ý tưởng táo bạo thành hiện thực huy hoàng.', 'Độc tài chuyên chế, áp đặt suy nghĩ cá nhân, nóng nảy và không chấp nhận sự phản biện.', 'Vị vua ngồi trên ngai chạm khắc thằn lằn cắn đuôi (Ouroboros) và ngọn lửa uy nghiêm. Đỉnh cao của tầm nhìn lãnh đạo, ý chí sắt đá và khả năng biến ý tưởng vĩ mô thành sự nghiệp hiển hách.', 'YES', 'Tầm nhìn lãnh đạo uy nghiêm và khả năng truyền cảm hứng dẫn dắt tập thể thành công rực rỡ.', 'Khoảng 1 tháng hoặc mùa hè rực lửa.', 'assets/cards/wands_14.jpg') ON DUPLICATE KEY UPDATE `name_vi` = VALUES(`name_vi`), `name_en` = VALUES(`name_en`), `arcana_type` = VALUES(`arcana_type`), `suit_element` = VALUES(`suit_element`), `keywords` = VALUES(`keywords`), `upright_meaning` = VALUES(`upright_meaning`), `reversed_meaning` = VALUES(`reversed_meaning`), `archetype_story` = VALUES(`archetype_story`), `yes_no_result` = VALUES(`yes_no_result`), `yes_no_reason` = VALUES(`yes_no_reason`), `time_prediction` = VALUES(`time_prediction`), `image_path` = VALUES(`image_path`);

-- [37/78] cups-1: Ace of Cups (Ace of Cups (Ách Ly))
INSERT INTO `TarotCard` (`card_id`, `name_vi`, `name_en`, `arcana_type`, `suit_element`, `keywords`, `upright_meaning`, `reversed_meaning`, `archetype_story`, `yes_no_result`, `yes_no_reason`, `time_prediction`, `image_path`) VALUES ('cups-1', 'Ace of Cups (Ách Ly)', 'Ace of Cups', 'Minor', 'Nước', 'Suối nguồn tình yêu, Trực giác nở rộ, Tràn trề cảm xúc, Chữa lành trái tim', 'Chén thánh tình yêu tràn trề dòng nước phúc lành. Trái tim bạn rộng mở đón nhận tình yêu trong sáng, sự bình an và sáng tạo vô tận.', 'Đè nén cảm xúc, trái tim tổn thương chưa lành, cảm thấy trống rỗng hoặc thất vọng trong tình cảm.', 'Chiếc chén vàng thánh thần tuôn trào năm dòng suối cảm xúc vào đầm sen thanh tịnh, chim bồ câu ngậm bánh thánh hạ xuống. Nguồn cội của tình yêu thương vô điều kiện và sự thức tỉnh tâm linh.', 'YES', 'Chiếc cốc tình yêu và niềm vui tinh thần đang tràn đầy; hãy mở lòng đón nhận hạnh phúc.', '1 tháng hoặc mùa hè (Cự Giải).', 'assets/cards/cups_01.jpg') ON DUPLICATE KEY UPDATE `name_vi` = VALUES(`name_vi`), `name_en` = VALUES(`name_en`), `arcana_type` = VALUES(`arcana_type`), `suit_element` = VALUES(`suit_element`), `keywords` = VALUES(`keywords`), `upright_meaning` = VALUES(`upright_meaning`), `reversed_meaning` = VALUES(`reversed_meaning`), `archetype_story` = VALUES(`archetype_story`), `yes_no_result` = VALUES(`yes_no_result`), `yes_no_reason` = VALUES(`yes_no_reason`), `time_prediction` = VALUES(`time_prediction`), `image_path` = VALUES(`image_path`);

-- [38/78] cups-2: Two of Cups (Two of Cups (Hai Ly))
INSERT INTO `TarotCard` (`card_id`, `name_vi`, `name_en`, `arcana_type`, `suit_element`, `keywords`, `upright_meaning`, `reversed_meaning`, `archetype_story`, `yes_no_result`, `yes_no_reason`, `time_prediction`, `image_path`) VALUES ('cups-2', 'Two of Cups (Hai Ly)', 'Two of Cups', 'Minor', 'Nước', 'Tâm đầu ý hợp, Kết nối sâu sắc, Tình yêu đôi lứa, Hợp tác hài hòa', 'Sự kết hợp hoàn hảo giữa hai tâm hồn, cùng nâng ly chia sẻ yêu thương và sự thấu hiểu bình đẳng tuyệt đối.', 'Hiểu lầm, mâu thuẫn rạn nứt, sự bất đồng quan điểm hoặc thiếu tôn trọng lẫn nhau.', 'Đôi nam nữ trao nhau chiếc chén ước nguyện dưới biểu tượng gậy thần Hermes (Caduceus) và đầu sư tử có cánh. Sự hòa hợp âm dương, tình yêu đích thực và sự gắn kết tâm hồn sâu sắc.', 'YES', 'Sự đồng điệu gắn kết của hai tâm hồn, tình cảm thăng hoa và hợp tác bền vững đôi bên cùng có lợi.', '2 tháng hoặc đầu mùa hè (khoảng 21/6 - 2/7).', 'assets/cards/cups_02.jpg') ON DUPLICATE KEY UPDATE `name_vi` = VALUES(`name_vi`), `name_en` = VALUES(`name_en`), `arcana_type` = VALUES(`arcana_type`), `suit_element` = VALUES(`suit_element`), `keywords` = VALUES(`keywords`), `upright_meaning` = VALUES(`upright_meaning`), `reversed_meaning` = VALUES(`reversed_meaning`), `archetype_story` = VALUES(`archetype_story`), `yes_no_result` = VALUES(`yes_no_result`), `yes_no_reason` = VALUES(`yes_no_reason`), `time_prediction` = VALUES(`time_prediction`), `image_path` = VALUES(`image_path`);

-- [39/78] cups-3: Three of Cups (Three of Cups (Ba Ly))
INSERT INTO `TarotCard` (`card_id`, `name_vi`, `name_en`, `arcana_type`, `suit_element`, `keywords`, `upright_meaning`, `reversed_meaning`, `archetype_story`, `yes_no_result`, `yes_no_reason`, `time_prediction`, `image_path`) VALUES ('cups-3', 'Three of Cups (Ba Ly)', 'Three of Cups', 'Minor', 'Nước', 'Tiệc tùng chúc mừng, Tình bạn tri kỷ, Niềm vui gắn kết, Cộng đồng hỗ trợ', 'Ba cô gái cùng nâng ly nhảy múa dưới chùm nho trĩu quả. Niềm vui sum họp bạn bè, tiệc tùng chúc mừng và tình thân ấm áp.', 'Tụ tập vui chơi quá đà, buôn chuyện nói xấu sau lưng, hoặc sự xuất hiện của người thứ ba gây xáo trộn.', 'Ba thiếu nữ nâng cao ba chiếc cốc kết vòng hoa dạo múa giữa vườn nho trĩu quả. Niềm vui gắn kết cộng đồng, tình bạn chân thành và sự sẻ chia hạnh phúc mùa màng.', 'YES', 'Niềm vui chia sẻ, lễ hội ăn mừng và sự nâng đỡ ấm áp từ bạn bè, hội nhóm.', '3 tháng hoặc giữa mùa hè (khoảng 3/7 - 12/7).', 'assets/cards/cups_03.jpg') ON DUPLICATE KEY UPDATE `name_vi` = VALUES(`name_vi`), `name_en` = VALUES(`name_en`), `arcana_type` = VALUES(`arcana_type`), `suit_element` = VALUES(`suit_element`), `keywords` = VALUES(`keywords`), `upright_meaning` = VALUES(`upright_meaning`), `reversed_meaning` = VALUES(`reversed_meaning`), `archetype_story` = VALUES(`archetype_story`), `yes_no_result` = VALUES(`yes_no_result`), `yes_no_reason` = VALUES(`yes_no_reason`), `time_prediction` = VALUES(`time_prediction`), `image_path` = VALUES(`image_path`);

-- [40/78] cups-4: Four of Cups (Four of Cups (Bốn Ly))
INSERT INTO `TarotCard` (`card_id`, `name_vi`, `name_en`, `arcana_type`, `suit_element`, `keywords`, `upright_meaning`, `reversed_meaning`, `archetype_story`, `yes_no_result`, `yes_no_reason`, `time_prediction`, `image_path`) VALUES ('cups-4', 'Four of Cups (Bốn Ly)', 'Four of Cups', 'Minor', 'Nước', 'Thờ ơ lãnh đạm, Bỏ lỡ cơ hội, Chán chường u uất, Thu mình ngẫm ngợi', 'Bạn đang ngồi khoanh tay dưới gốc cây nhìn ba chiếc ly cũ mà thờ ơ không nhận ra chiếc ly thứ tư đầy phúc lành đang được đưa tới.', 'Thức tỉnh khỏi cơn u mê, mở mắt nhận ra cơ hội quý giá và sẵn sàng đón nhận niềm vui mới.', 'Chàng trai ngồi khoanh tay dưới gốc cây thờ ơ trước ba chiếc cốc trước mặt, không buồn để ý chiếc cốc thứ tư đang được bàn tay vũ trụ trao tặng. Sự chán nản và mù quáng cảm xúc.', 'MAYBE', 'Sự thờ ơ, chán nản khiến bạn bỏ qua chiếc cốc kỳ diệu vũ trụ đang trao tặng; hãy mở mắt nhìn lại.', '4 tháng hoặc giai đoạn cảm xúc lắng đọng (khoảng 13/7 - 22/7).', 'assets/cards/cups_04.jpg') ON DUPLICATE KEY UPDATE `name_vi` = VALUES(`name_vi`), `name_en` = VALUES(`name_en`), `arcana_type` = VALUES(`arcana_type`), `suit_element` = VALUES(`suit_element`), `keywords` = VALUES(`keywords`), `upright_meaning` = VALUES(`upright_meaning`), `reversed_meaning` = VALUES(`reversed_meaning`), `archetype_story` = VALUES(`archetype_story`), `yes_no_result` = VALUES(`yes_no_result`), `yes_no_reason` = VALUES(`yes_no_reason`), `time_prediction` = VALUES(`time_prediction`), `image_path` = VALUES(`image_path`);

-- [41/78] cups-5: Five of Cups (Five of Cups (Năm Ly))
INSERT INTO `TarotCard` (`card_id`, `name_vi`, `name_en`, `arcana_type`, `suit_element`, `keywords`, `upright_meaning`, `reversed_meaning`, `archetype_story`, `yes_no_result`, `yes_no_reason`, `time_prediction`, `image_path`) VALUES ('cups-5', 'Five of Cups (Năm Ly)', 'Five of Cups', 'Minor', 'Nước', 'Nuối tiếc mất mát, Đau buồn quá khứ, Nhìn về phía trước, Hy vọng còn lại', 'Bạn trùm áo đen đau buồn nhìn ba chiếc ly bị đổ mà quên mất rằng sau lưng vẫn còn hai chiếc ly nguyên vẹn và cây cầu dẫn về lâu đài.', 'Vượt qua nỗi đau buồn, chấp nhận quá khứ đã qua và quay lại với cuộc sống thực tại.', 'Người áo đen cúi đầu xót xa nhìn ba chiếc cốc đổ rượu lênh láng trên mặt đất, quên mất hai chiếc cốc vẫn còn nguyên vẹn phía sau lưng. Nỗi đau mất mát và sự chấp niệm quá khứ.', 'NO', 'Bạn đang mải đau buồn nhìn ba chiếc cốc đổ mà quên mất hai chiếc cốc còn nguyên phía sau; hãy quay đầu lại.', '5 tháng hoặc mùa Bọ Cạp (khoảng 23/10 - 2/11).', 'assets/cards/cups_05.jpg') ON DUPLICATE KEY UPDATE `name_vi` = VALUES(`name_vi`), `name_en` = VALUES(`name_en`), `arcana_type` = VALUES(`arcana_type`), `suit_element` = VALUES(`suit_element`), `keywords` = VALUES(`keywords`), `upright_meaning` = VALUES(`upright_meaning`), `reversed_meaning` = VALUES(`reversed_meaning`), `archetype_story` = VALUES(`archetype_story`), `yes_no_result` = VALUES(`yes_no_result`), `yes_no_reason` = VALUES(`yes_no_reason`), `time_prediction` = VALUES(`time_prediction`), `image_path` = VALUES(`image_path`);

-- [42/78] cups-6: Six of Cups (Six of Cups (Sáu Ly))
INSERT INTO `TarotCard` (`card_id`, `name_vi`, `name_en`, `arcana_type`, `suit_element`, `keywords`, `upright_meaning`, `reversed_meaning`, `archetype_story`, `yes_no_result`, `yes_no_reason`, `time_prediction`, `image_path`) VALUES ('cups-6', 'Six of Cups (Sáu Ly)', 'Six of Cups', 'Minor', 'Nước', 'Kỷ niệm tuổi thơ, Gặp lại người xưa, Sự ngây thơ trong sáng, Hoài niệm ngọt ngào', 'Cậu bé trao đóa hoa trong chiếc ly cho cô bé trước tòa lâu đài cổ. Kỷ niệm tuổi thơ ngọt ngào ùa về, gặp lại cố nhân hoặc nhận được món quà vô tư.', 'Mắc kẹt trong quá khứ không chịu lớn lên, hoặc dứt bỏ được ảo ảnh xưa cũ để sống cho hiện tại.', 'Hai đứa trẻ thơ ngây trong lâu đài cổ kính trao nhau chiếc cốc chứa đầy hoa trắng thơm ngát. Sự hoài niệm ngọt ngào, lòng vị tha và tình cảm trong sáng từ miền ký ức tuổi thơ.', 'YES', 'Kỷ niệm ngọt ngào của tuổi thơ, sự tái ngộ nhân duyên cũ và tình cảm chân thành thuần khiết.', '6 tháng hoặc giữa mùa Bọ Cạp (khoảng 3/11 - 12/11).', 'assets/cards/cups_06.jpg') ON DUPLICATE KEY UPDATE `name_vi` = VALUES(`name_vi`), `name_en` = VALUES(`name_en`), `arcana_type` = VALUES(`arcana_type`), `suit_element` = VALUES(`suit_element`), `keywords` = VALUES(`keywords`), `upright_meaning` = VALUES(`upright_meaning`), `reversed_meaning` = VALUES(`reversed_meaning`), `archetype_story` = VALUES(`archetype_story`), `yes_no_result` = VALUES(`yes_no_result`), `yes_no_reason` = VALUES(`yes_no_reason`), `time_prediction` = VALUES(`time_prediction`), `image_path` = VALUES(`image_path`);

-- [43/78] cups-7: Seven of Cups (Seven of Cups (Bảy Ly))
INSERT INTO `TarotCard` (`card_id`, `name_vi`, `name_en`, `arcana_type`, `suit_element`, `keywords`, `upright_meaning`, `reversed_meaning`, `archetype_story`, `yes_no_result`, `yes_no_reason`, `time_prediction`, `image_path`) VALUES ('cups-7', 'Seven of Cups (Bảy Ly)', 'Seven of Cups', 'Minor', 'Nước', 'Ảo tưởng mộng mơ, Quá nhiều lựa chọn, Lạc lối mê cung, Cần tỉnh táo thực tế', 'Bảy chiếc ly hiện lên giữa những đám mây chứa đầy châu báu, rồng, lâu đài và cám dỗ. Bạn đứng trước quá nhiều lựa chọn nhưng cẩn thận ảo ảnh!', 'Tỉnh mộng, xóa tan sương mù ảo tưởng, đưa ra lựa chọn thực tế và tập trung vào một mục tiêu cụ thể.', 'Hình bóng người đàn ông sững sờ trước bảy chiếc cốc bồng bềnh trong mây mờ, chứa đựng rắn độc, lâu đài, ngọc quý, vòng nguyệt quế và quỷ dữ. Ảo mộng và cám dỗ của dục vọng hư vô.', 'MAYBE', 'Quá nhiều ảo tưởng và lựa chọn viển vông; cần kéo tâm trí về thực tại tỉnh táo để chọn một điều duy nhất.', '7 tháng hoặc thời điểm trăng tròn (khoảng 13/11 - 22/11).', 'assets/cards/cups_07.jpg') ON DUPLICATE KEY UPDATE `name_vi` = VALUES(`name_vi`), `name_en` = VALUES(`name_en`), `arcana_type` = VALUES(`arcana_type`), `suit_element` = VALUES(`suit_element`), `keywords` = VALUES(`keywords`), `upright_meaning` = VALUES(`upright_meaning`), `reversed_meaning` = VALUES(`reversed_meaning`), `archetype_story` = VALUES(`archetype_story`), `yes_no_result` = VALUES(`yes_no_result`), `yes_no_reason` = VALUES(`yes_no_reason`), `time_prediction` = VALUES(`time_prediction`), `image_path` = VALUES(`image_path`);

-- [44/78] cups-8: Eight of Cups (Eight of Cups (Tám Ly))
INSERT INTO `TarotCard` (`card_id`, `name_vi`, `name_en`, `arcana_type`, `suit_element`, `keywords`, `upright_meaning`, `reversed_meaning`, `archetype_story`, `yes_no_result`, `yes_no_reason`, `time_prediction`, `image_path`) VALUES ('cups-8', 'Eight of Cups (Tám Ly)', 'Eight of Cups', 'Minor', 'Nước', 'Dứt áo ra đi, Tìm kiếm ý nghĩa cao hơn, Rời bỏ vùng an toàn, Hành trình nội tâm', 'Người lữ khách chống gậy quay lưng bước đi trong đêm trăng, bỏ lại tám chiếc ly đã dày công xếp đặt để lên đường tìm kiếm chân trời ý nghĩa hơn.', 'Sợ hãi không dám dứt bỏ điều đã hết hạn sử dụng, bế tắc trong vùng an toàn tẻ nhạt.', 'Lữ khách quay lưng rời bỏ tám chiếc cốc xếp chồng ngay ngắn, chống gậy đơn độc bước qua dòng suối hướng lên núi cao dưới trăng khuyết. Sự thức tỉnh và can đảm rời bỏ cái quen thuộc.', 'MAYBE', 'Sự can đảm dứt áo ra đi khỏi những gì không còn thỏa mãn tâm hồn để tìm kiếm ý nghĩa cao hơn.', '8 tháng hoặc mùa Song Ngư (khoảng 19/2 - 28/2).', 'assets/cards/cups_08.jpg') ON DUPLICATE KEY UPDATE `name_vi` = VALUES(`name_vi`), `name_en` = VALUES(`name_en`), `arcana_type` = VALUES(`arcana_type`), `suit_element` = VALUES(`suit_element`), `keywords` = VALUES(`keywords`), `upright_meaning` = VALUES(`upright_meaning`), `reversed_meaning` = VALUES(`reversed_meaning`), `archetype_story` = VALUES(`archetype_story`), `yes_no_result` = VALUES(`yes_no_result`), `yes_no_reason` = VALUES(`yes_no_reason`), `time_prediction` = VALUES(`time_prediction`), `image_path` = VALUES(`image_path`);

-- [45/78] cups-9: Nine of Cups (Nine of Cups (Chín Ly))
INSERT INTO `TarotCard` (`card_id`, `name_vi`, `name_en`, `arcana_type`, `suit_element`, `keywords`, `upright_meaning`, `reversed_meaning`, `archetype_story`, `yes_no_result`, `yes_no_reason`, `time_prediction`, `image_path`) VALUES ('cups-9', 'Nine of Cups (Chín Ly)', 'Nine of Cups', 'Minor', 'Nước', 'Ước nguyện thành hiện thực, Thỏa mãn viên mãn, Hạnh phúc tự thân, An lạc đủ đầy', 'Lá bài của \'Ước gì được nấy\'! Người đàn ông mỉm cười hài lòng trước chín chiếc ly vàng xếp hàng ngay ngắn. Mọi ước nguyện của bạn sắp thành sự thật.', 'Thỏa mãn nhất thời, tham lam đòi hỏi quá mức, hoặc cảm giác trống rỗng dù đã đạt được điều mình muốn.', 'Người đàn ông bệ vệ ngồi khoanh tay mỉm cười mãn nguyện trước bức màn xanh treo chín chiếc cúp vàng lấp lánh. Lá bài của ước nguyện thành sự thật và sự thỏa mãn viên mãn.', 'YES', 'Lá bài ước nguyện thành tựu; sự thỏa mãn sâu sắc cả về cảm xúc lẫn chất lượng sống.', '9 tháng hoặc giữa mùa Song Ngư (khoảng 1/3 - 10/3).', 'assets/cards/cups_09.jpg') ON DUPLICATE KEY UPDATE `name_vi` = VALUES(`name_vi`), `name_en` = VALUES(`name_en`), `arcana_type` = VALUES(`arcana_type`), `suit_element` = VALUES(`suit_element`), `keywords` = VALUES(`keywords`), `upright_meaning` = VALUES(`upright_meaning`), `reversed_meaning` = VALUES(`reversed_meaning`), `archetype_story` = VALUES(`archetype_story`), `yes_no_result` = VALUES(`yes_no_result`), `yes_no_reason` = VALUES(`yes_no_reason`), `time_prediction` = VALUES(`time_prediction`), `image_path` = VALUES(`image_path`);

-- [46/78] cups-10: Ten of Cups (Ten of Cups (Mười Ly))
INSERT INTO `TarotCard` (`card_id`, `name_vi`, `name_en`, `arcana_type`, `suit_element`, `keywords`, `upright_meaning`, `reversed_meaning`, `archetype_story`, `yes_no_result`, `yes_no_reason`, `time_prediction`, `image_path`) VALUES ('cups-10', 'Ten of Cups (Mười Ly)', 'Ten of Cups', 'Minor', 'Nước', 'Gia đình hạnh phúc, Cầu vồng bình an, Hòa thuận viên mãn, Tổ ấm trọn vẹn', 'Cặp vợ chồng giang tay hạnh phúc bên hai đứa trẻ nhảy múa, dưới bầu trời có dải cầu vồng kết bằng mười chiếc ly vàng. Hạnh phúc gia đình trọn vẹn nhất.', 'Bất hòa trong gia đình, xung đột giá trị sống giữa các thế hệ, hoặc sự đổ vỡ của tổ ấm.', 'Gia đình hạnh phúc cùng hai đứa trẻ nhảy múa dưới dải cầu vồng kết bằng mười chiếc cốc vàng rực rỡ trên bầu trời quê hương. Sự viên mãn tột cùng của tình yêu thương gia đình.', 'YES', 'Hạnh phúc gia đình viên mãn, tình yêu trọn vẹn và sự bình an ngập tràn dưới cầu vồng ân sủng.', '10 tháng hoặc cuối mùa Song Ngư (khoảng 11/3 - 20/3).', 'assets/cards/cups_10.jpg') ON DUPLICATE KEY UPDATE `name_vi` = VALUES(`name_vi`), `name_en` = VALUES(`name_en`), `arcana_type` = VALUES(`arcana_type`), `suit_element` = VALUES(`suit_element`), `keywords` = VALUES(`keywords`), `upright_meaning` = VALUES(`upright_meaning`), `reversed_meaning` = VALUES(`reversed_meaning`), `archetype_story` = VALUES(`archetype_story`), `yes_no_result` = VALUES(`yes_no_result`), `yes_no_reason` = VALUES(`yes_no_reason`), `time_prediction` = VALUES(`time_prediction`), `image_path` = VALUES(`image_path`);

-- [47/78] cups-11: Page of Cups (Page of Cups (Tiểu Đồng Ly))
INSERT INTO `TarotCard` (`card_id`, `name_vi`, `name_en`, `arcana_type`, `suit_element`, `keywords`, `upright_meaning`, `reversed_meaning`, `archetype_story`, `yes_no_result`, `yes_no_reason`, `time_prediction`, `image_path`) VALUES ('cups-11', 'Page of Cups (Tiểu Đồng Ly)', 'Page of Cups', 'Minor', 'Nước', 'Thông điệp tình yêu, Trực giác nhạy cảm, Tâm hồn mơ mộng, Bất ngờ ngọt ngào', 'Chàng trai trẻ ngạc nhiên nhìn chú cá nhỏ nhảy múa trong chiếc ly trên tay mình. Tin nhắn tình yêu dễ thương hoặc lời mời gọi hẹn hò bất ngờ.', 'Cảm xúc ủy mị, dễ tự ái tổn thương, thất hứa hoặc nhận tin nhắn làm bạn hụt hẫng.', 'Chàng trai trẻ duyên dáng đứng bên bờ biển ngắm nhìn chú cá nhỏ nhảy múa trong chiếc cốc trên tay. Thông điệp bất ngờ từ tiềm thức, sự mộng mơ và trực cảm tâm hồn.', 'YES', 'Thông điệp ngọt ngào từ trái tim, sự ngây thơ trực cảm và cơ hội tình cảm mới chớm.', 'Vài tuần tới hoặc đầu mùa Nước.', 'assets/cards/cups_11.jpg') ON DUPLICATE KEY UPDATE `name_vi` = VALUES(`name_vi`), `name_en` = VALUES(`name_en`), `arcana_type` = VALUES(`arcana_type`), `suit_element` = VALUES(`suit_element`), `keywords` = VALUES(`keywords`), `upright_meaning` = VALUES(`upright_meaning`), `reversed_meaning` = VALUES(`reversed_meaning`), `archetype_story` = VALUES(`archetype_story`), `yes_no_result` = VALUES(`yes_no_result`), `yes_no_reason` = VALUES(`yes_no_reason`), `time_prediction` = VALUES(`time_prediction`), `image_path` = VALUES(`image_path`);

-- [48/78] cups-12: Knight of Cups (Knight of Cups (Hiệp Sĩ Ly))
INSERT INTO `TarotCard` (`card_id`, `name_vi`, `name_en`, `arcana_type`, `suit_element`, `keywords`, `upright_meaning`, `reversed_meaning`, `archetype_story`, `yes_no_result`, `yes_no_reason`, `time_prediction`, `image_path`) VALUES ('cups-12', 'Knight of Cups (Hiệp Sĩ Ly)', 'Knight of Cups', 'Minor', 'Nước', 'Bạch mã hoàng tử, Lời mời lãng mạn, Trực giác dẫn lối, Theo đuổi ước mơ', 'Kỵ sĩ phong nhã cưỡi ngựa thong dong mang theo chiếc ly vàng tràn đầy tình cảm. Lời mời hẹn hò lãng mạn hoặc theo đuổi lý tưởng nghệ thuật cao đẹp.', 'Ảo tưởng tình cảm, người yêu lăng nhăng nói lời ngon ngọt nhưng thiếu hành động thực tế.', 'Kỵ sĩ áo giáp thêu hình cá bơi lội cưỡi ngựa trắng thong thả bước qua dòng suối hiền hòa, tay nâng cao chiếc cốc tình yêu. Sứ giả của sự lãng mạn, hòa giải và lý tưởng thẩm mỹ.', 'YES', 'Chàng kỵ sĩ lãng mạn mang đến lời mời hẹn hò, sự hòa giải hoặc cơ hội nghệ thuật đầy cảm hứng.', 'Khoảng 1 - 2 tháng hoặc mùa hè.', 'assets/cards/cups_12.jpg') ON DUPLICATE KEY UPDATE `name_vi` = VALUES(`name_vi`), `name_en` = VALUES(`name_en`), `arcana_type` = VALUES(`arcana_type`), `suit_element` = VALUES(`suit_element`), `keywords` = VALUES(`keywords`), `upright_meaning` = VALUES(`upright_meaning`), `reversed_meaning` = VALUES(`reversed_meaning`), `archetype_story` = VALUES(`archetype_story`), `yes_no_result` = VALUES(`yes_no_result`), `yes_no_reason` = VALUES(`yes_no_reason`), `time_prediction` = VALUES(`time_prediction`), `image_path` = VALUES(`image_path`);

-- [49/78] cups-13: Queen of Cups (Queen of Cups (Hoàng Hậu Ly))
INSERT INTO `TarotCard` (`card_id`, `name_vi`, `name_en`, `arcana_type`, `suit_element`, `keywords`, `upright_meaning`, `reversed_meaning`, `archetype_story`, `yes_no_result`, `yes_no_reason`, `time_prediction`, `image_path`) VALUES ('cups-13', 'Queen of Cups (Hoàng Hậu Ly)', 'Queen of Cups', 'Minor', 'Nước', 'Lòng trắc ẩn bao la, Trực giác siêu phàm, Thấu cảm tâm hồn, Chữa lành ấm áp', 'Người phụ nữ ngồi bên bờ biển ngắm nhìn chiếc ly nạm đá quý tinh xảo. Bà là hiện thân của tình mẫu tử, lòng trắc ẩn và sự thấu cảm sâu sắc.', 'Bất ổn cảm xúc, hay suy diễn lung tung, trầm cảm hoặc bị người khác lợi dụng lòng tốt.', 'Hoàng hậu ngồi trên ngai vàng chạm khắc thiên thần biển, ngắm nhìn chiếc cúp tinh xảo có nắp đóng kín bên bờ đại dương bao la. Biểu tượng của trực giác thấu suốt và sự chữa lành thầm lặng.', 'YES', 'Trực giác nhạy bén, tấm lòng nhân hậu thấu suốt cảm xúc người khác như mặt hồ yên ả.', 'Khoảng 2 - 3 tháng hoặc mùa hè mát mẻ.', 'assets/cards/cups_13.jpg') ON DUPLICATE KEY UPDATE `name_vi` = VALUES(`name_vi`), `name_en` = VALUES(`name_en`), `arcana_type` = VALUES(`arcana_type`), `suit_element` = VALUES(`suit_element`), `keywords` = VALUES(`keywords`), `upright_meaning` = VALUES(`upright_meaning`), `reversed_meaning` = VALUES(`reversed_meaning`), `archetype_story` = VALUES(`archetype_story`), `yes_no_result` = VALUES(`yes_no_result`), `yes_no_reason` = VALUES(`yes_no_reason`), `time_prediction` = VALUES(`time_prediction`), `image_path` = VALUES(`image_path`);

-- [50/78] cups-14: King of Cups (King of Cups (Vua Ly))
INSERT INTO `TarotCard` (`card_id`, `name_vi`, `name_en`, `arcana_type`, `suit_element`, `keywords`, `upright_meaning`, `reversed_meaning`, `archetype_story`, `yes_no_result`, `yes_no_reason`, `time_prediction`, `image_path`) VALUES ('cups-14', 'King of Cups (Vua Ly)', 'King of Cups', 'Minor', 'Nước', 'Làm chủ cảm xúc, Thông thái độ lượng, Người bảo trợ ấm áp, Cân bằng tâm trí', 'Vị vua ngồi vững chãi trên ngai vàng giữa biển khơi dậy sóng mà tà áo không hề dính nước. Bậc thầy kiểm soát cảm xúc với trí tuệ và sự nhân từ.', 'Thao túng cảm xúc, lạnh lùng tàn nhẫn, nghiện ngập hoặc che giấu sự giận dữ ngầm dưới vẻ ngoài điềm tĩnh.', 'Vị vua ngồi trên ngai vàng nổi trên mặt biển cuộn sóng, tay cầm cúp và quyền trượng, dây chuyền hình cá trước ngực. Khả năng làm chủ cảm xúc phi thường và sự điềm tĩnh trước giông bão đời người.', 'YES', 'Bậc thầy làm chủ cảm xúc, lòng khoan dung độ lượng và sự thấu hiểu sâu sắc giúp cân bằng mọi quan hệ.', 'Khoảng 3 tháng hoặc thời điểm cảm xúc chín muồi.', 'assets/cards/cups_14.jpg') ON DUPLICATE KEY UPDATE `name_vi` = VALUES(`name_vi`), `name_en` = VALUES(`name_en`), `arcana_type` = VALUES(`arcana_type`), `suit_element` = VALUES(`suit_element`), `keywords` = VALUES(`keywords`), `upright_meaning` = VALUES(`upright_meaning`), `reversed_meaning` = VALUES(`reversed_meaning`), `archetype_story` = VALUES(`archetype_story`), `yes_no_result` = VALUES(`yes_no_result`), `yes_no_reason` = VALUES(`yes_no_reason`), `time_prediction` = VALUES(`time_prediction`), `image_path` = VALUES(`image_path`);

-- [51/78] swords-1: Ace of Swords (Ace of Swords (Ách Kiếm))
INSERT INTO `TarotCard` (`card_id`, `name_vi`, `name_en`, `arcana_type`, `suit_element`, `keywords`, `upright_meaning`, `reversed_meaning`, `archetype_story`, `yes_no_result`, `yes_no_reason`, `time_prediction`, `image_path`) VALUES ('swords-1', 'Ace of Swords (Ách Kiếm)', 'Ace of Swords', 'Minor', 'Khí', 'Chân lý sắc bén, Đột phá tư duy, Sự thật tỏ tường, Quyết định dứt khoát', 'Bàn tay từ mây đưa ra thanh kiếm đội vương miện lá nguyệt quế. Sự thật sáng tỏ như ban ngày, tư duy sắc bén cắt đứt mọi hoài nghi.', 'Tư duy bế tắc, lời nói cay độc làm tổn thương người khác, hoặc lạm dụng trí thông minh vào việc xấu.', 'Bàn tay vũ trụ vươn ra từ đám mây nâng thanh kiếm hai lưỡi cắm vương miện kết lá cọ và ô liu. Sức mạnh tuyệt đối của lý trí, sự thật khách quan và chân lý chiến thắng dối lừa.', 'YES', 'Lưỡi kiếm chân lý chém tan sương mù dối trá; sự sáng suốt và công lý sẽ mang lại thắng lợi dứt khoát.', '1 tuần hoặc mùa thu (Thiên Bình).', 'assets/cards/swords_01.jpg') ON DUPLICATE KEY UPDATE `name_vi` = VALUES(`name_vi`), `name_en` = VALUES(`name_en`), `arcana_type` = VALUES(`arcana_type`), `suit_element` = VALUES(`suit_element`), `keywords` = VALUES(`keywords`), `upright_meaning` = VALUES(`upright_meaning`), `reversed_meaning` = VALUES(`reversed_meaning`), `archetype_story` = VALUES(`archetype_story`), `yes_no_result` = VALUES(`yes_no_result`), `yes_no_reason` = VALUES(`yes_no_reason`), `time_prediction` = VALUES(`time_prediction`), `image_path` = VALUES(`image_path`);

-- [52/78] swords-2: Two of Swords (Two of Swords (Hai Kiếm))
INSERT INTO `TarotCard` (`card_id`, `name_vi`, `name_en`, `arcana_type`, `suit_element`, `keywords`, `upright_meaning`, `reversed_meaning`, `archetype_story`, `yes_no_result`, `yes_no_reason`, `time_prediction`, `image_path`) VALUES ('swords-2', 'Two of Swords (Hai Kiếm)', 'Two of Swords', 'Minor', 'Khí', 'Tiến thoái lưỡng nan, Bịt mắt trốn tránh, Bế tắc lựa chọn, Tìm kiếm thỏa hiệp', 'Người phụ nữ bịt mắt bắt chéo hai thanh kiếm trước ngực bên bờ biển tĩnh lặng. Bạn đang đứng giữa hai ngã rẽ khó xử và cố tình né tránh sự thật.', 'Tháo bỏ dải băng bịt mắt, đối diện với sự thật dù đau lòng để đưa ra quyết định dứt khoát.', 'Thiếu nữ bịt mắt ngồi trên bờ đá trước biển đêm, hai tay bắt chéo giữ hai thanh kiếm nặng trĩu. Sự bế tắc do lý trí từ chối đối diện sự thật nhức nhối và đè nén cảm xúc.', 'MAYBE', 'Bạn đang bịt mắt né tránh đối diện với sự thật nhức nhối; cần hạ kiếm và mở lòng lắng nghe trực giác.', '2 tuần hoặc thời điểm trăng khuyết (khoảng 23/9 - 2/10).', 'assets/cards/swords_02.jpg') ON DUPLICATE KEY UPDATE `name_vi` = VALUES(`name_vi`), `name_en` = VALUES(`name_en`), `arcana_type` = VALUES(`arcana_type`), `suit_element` = VALUES(`suit_element`), `keywords` = VALUES(`keywords`), `upright_meaning` = VALUES(`upright_meaning`), `reversed_meaning` = VALUES(`reversed_meaning`), `archetype_story` = VALUES(`archetype_story`), `yes_no_result` = VALUES(`yes_no_result`), `yes_no_reason` = VALUES(`yes_no_reason`), `time_prediction` = VALUES(`time_prediction`), `image_path` = VALUES(`image_path`);

-- [53/78] swords-3: Three of Swords (Three of Swords (Ba Kiếm))
INSERT INTO `TarotCard` (`card_id`, `name_vi`, `name_en`, `arcana_type`, `suit_element`, `keywords`, `upright_meaning`, `reversed_meaning`, `archetype_story`, `yes_no_result`, `yes_no_reason`, `time_prediction`, `image_path`) VALUES ('swords-3', 'Three of Swords (Ba Kiếm)', 'Three of Swords', 'Minor', 'Khí', 'Trái tim tan vỡ, Nỗi đau chia cắt, Sự phản bội cay đắng, Bài học trưởng thành', 'Trái tim bị ba thanh kiếm đâm xuyên giữa cơn mưa giông mù mịt. Nỗi đau thất tình, sự phản bội hoặc mất mát đau đớn không thể tránh khỏi.', 'Vết thương lòng bắt đầu lành sẹo, vượt qua nỗi đau phản bội, tha thứ để bước tiếp.', 'Trái tim đỏ thắm bị ba lưỡi kiếm đâm xuyên qua giữa bầu trời mây đen vần vũ và mưa tuôn xối xả. Nỗi đau đớn tột cùng của sự chia ly, phản bội và bài học trưởng thành qua tan vỡ.', 'NO', 'Nỗi đau thấu tim, sự chia ly hoặc phản bội; cần để nước mắt rửa trôi vết thương lòng trước khi đưa ra quyết định.', '3 tuần hoặc mùa thu nhiều gió (khoảng 3/10 - 12/10).', 'assets/cards/swords_03.jpg') ON DUPLICATE KEY UPDATE `name_vi` = VALUES(`name_vi`), `name_en` = VALUES(`name_en`), `arcana_type` = VALUES(`arcana_type`), `suit_element` = VALUES(`suit_element`), `keywords` = VALUES(`keywords`), `upright_meaning` = VALUES(`upright_meaning`), `reversed_meaning` = VALUES(`reversed_meaning`), `archetype_story` = VALUES(`archetype_story`), `yes_no_result` = VALUES(`yes_no_result`), `yes_no_reason` = VALUES(`yes_no_reason`), `time_prediction` = VALUES(`time_prediction`), `image_path` = VALUES(`image_path`);

-- [54/78] swords-4: Four of Swords (Four of Swords (Bốn Kiếm))
INSERT INTO `TarotCard` (`card_id`, `name_vi`, `name_en`, `arcana_type`, `suit_element`, `keywords`, `upright_meaning`, `reversed_meaning`, `archetype_story`, `yes_no_result`, `yes_no_reason`, `time_prediction`, `image_path`) VALUES ('swords-4', 'Four of Swords (Bốn Kiếm)', 'Four of Swords', 'Minor', 'Khí', 'Nghỉ ngơi hồi phục, Tịnh dưỡng tâm trí, Tạm dừng trận chiến, Thiền định tĩnh tâm', 'Hiệp sĩ nằm chắp tay tịnh dưỡng trên ngôi mộ đá trong nhà thờ, ba thanh kiếm treo trên tường và một thanh kiếm dưới thân. Hãy nghỉ ngơi để nạp lại năng lượng!', 'Thức tỉnh sau giai đoạn kiệt sức, quay trở lại nhịp sống hoặc bị ép phải làm việc khi chưa bình phục.', 'Hiệp sĩ nằm tịnh dưỡng trên lăng mộ đá với ba thanh kiếm treo trên tường và một thanh kiếm đặt bên cạnh, cửa sổ kính màu chiếu sáng. Khoảng lặng tĩnh tâm và hồi phục sinh lực sau chiến trận.', 'MAYBE', 'Thời điểm cơ thể và tâm trí cần được nghỉ ngơi phục hồi sau chuỗi ngày kiệt quệ; tạm hoãn hành động lúc này.', '4 tuần (khoảng 1 tháng) nghỉ ngơi tịnh dưỡng (khoảng 13/10 - 22/10).', 'assets/cards/swords_04.jpg') ON DUPLICATE KEY UPDATE `name_vi` = VALUES(`name_vi`), `name_en` = VALUES(`name_en`), `arcana_type` = VALUES(`arcana_type`), `suit_element` = VALUES(`suit_element`), `keywords` = VALUES(`keywords`), `upright_meaning` = VALUES(`upright_meaning`), `reversed_meaning` = VALUES(`reversed_meaning`), `archetype_story` = VALUES(`archetype_story`), `yes_no_result` = VALUES(`yes_no_result`), `yes_no_reason` = VALUES(`yes_no_reason`), `time_prediction` = VALUES(`time_prediction`), `image_path` = VALUES(`image_path`);

-- [55/78] swords-5: Five of Swords (Five of Swords (Năm Kiếm))
INSERT INTO `TarotCard` (`card_id`, `name_vi`, `name_en`, `arcana_type`, `suit_element`, `keywords`, `upright_meaning`, `reversed_meaning`, `archetype_story`, `yes_no_result`, `yes_no_reason`, `time_prediction`, `image_path`) VALUES ('swords-5', 'Five of Swords (Năm Kiếm)', 'Five of Swords', 'Minor', 'Khí', 'Thắng làm vua thua làm giặc, Xung đột cay đắng, Tổn hại danh dự, Rút lui chiến lược', 'Người đàn ông cười đắc thắng ôm lấy các thanh kiếm trong khi đối thủ thất thểu quay đi. Chiến thắng bằng mọi giá nhưng để lại sự cô độc và thù hận.', 'Hòa giải xung đột, chấm dứt thù hận, hoặc nhận ra cái giá quá đắt của sự hiếu thắng.', 'Kẻ chiến thắng mỉm cười xảo quyệt thu gom các thanh kiếm trong khi hai kẻ bại trận cúi đầu lầm lũi bỏ đi bờ biển gió lốc. Thắng lợi cay đắng làm tổn hại mối quan hệ và danh dự.', 'NO', 'Thắng lợi kiểu Pyrrhus - cái tôi giành phần thắng nhưng mối quan hệ tan vỡ; hãy rút lui để bảo toàn phẩm giá.', '5 tuần hoặc mùa Bảo Bình (khoảng 20/1 - 29/1).', 'assets/cards/swords_05.jpg') ON DUPLICATE KEY UPDATE `name_vi` = VALUES(`name_vi`), `name_en` = VALUES(`name_en`), `arcana_type` = VALUES(`arcana_type`), `suit_element` = VALUES(`suit_element`), `keywords` = VALUES(`keywords`), `upright_meaning` = VALUES(`upright_meaning`), `reversed_meaning` = VALUES(`reversed_meaning`), `archetype_story` = VALUES(`archetype_story`), `yes_no_result` = VALUES(`yes_no_result`), `yes_no_reason` = VALUES(`yes_no_reason`), `time_prediction` = VALUES(`time_prediction`), `image_path` = VALUES(`image_path`);

-- [56/78] swords-6: Six of Swords (Six of Swords (Sáu Kiếm))
INSERT INTO `TarotCard` (`card_id`, `name_vi`, `name_en`, `arcana_type`, `suit_element`, `keywords`, `upright_meaning`, `reversed_meaning`, `archetype_story`, `yes_no_result`, `yes_no_reason`, `time_prediction`, `image_path`) VALUES ('swords-6', 'Six of Swords (Sáu Kiếm)', 'Six of Swords', 'Minor', 'Khí', 'Rời bỏ vùng sóng gió, Hành trình chữa lành, Chuyển tiếp êm đềm, Tương lai yên bình', 'Chiếc thuyền chở hai mẹ con cùng sáu thanh kiếm chèo từ vùng nước gợn sóng sang bờ bến phẳng lặng. Bạn đang bỏ lại giông bão phía sau để đến bến bình yên.', 'Mắc kẹt giữa dòng nước xiết, quá khứ đeo bám dai dẳng không cho bạn thoát ra.', 'Người chèo đò chở hai mẹ con cùng sáu thanh kiếm cắm trên mạn thuyền rời vùng nước xoáy tiến sang vùng nước êm đềm phía trước. Hành trình chữa lành và thoát khỏi gian truân.', 'YES', 'Chiếc thuyền đang chèo qua vùng nước động để hướng về bờ bến bình yên; giông bão sắp lùi lại phía sau.', '6 tuần hoặc thời điểm chuyển mùa (khoảng 30/1 - 8/2).', 'assets/cards/swords_06.jpg') ON DUPLICATE KEY UPDATE `name_vi` = VALUES(`name_vi`), `name_en` = VALUES(`name_en`), `arcana_type` = VALUES(`arcana_type`), `suit_element` = VALUES(`suit_element`), `keywords` = VALUES(`keywords`), `upright_meaning` = VALUES(`upright_meaning`), `reversed_meaning` = VALUES(`reversed_meaning`), `archetype_story` = VALUES(`archetype_story`), `yes_no_result` = VALUES(`yes_no_result`), `yes_no_reason` = VALUES(`yes_no_reason`), `time_prediction` = VALUES(`time_prediction`), `image_path` = VALUES(`image_path`);

-- [57/78] swords-7: Seven of Swords (Seven of Swords (Bảy Kiếm))
INSERT INTO `TarotCard` (`card_id`, `name_vi`, `name_en`, `arcana_type`, `suit_element`, `keywords`, `upright_meaning`, `reversed_meaning`, `archetype_story`, `yes_no_result`, `yes_no_reason`, `time_prediction`, `image_path`) VALUES ('swords-7', 'Seven of Swords (Bảy Kiếm)', 'Seven of Swords', 'Minor', 'Khí', 'Hành động lén lút, Chiến thuật bí mật, Cảnh giác lừa dối, Tự làm tự chịu', 'Kẻ trộm nhón chân ôm năm thanh kiếm chuồn khỏi doanh trại trong khi hai thanh kiếm vẫn cắm tại chỗ. Cảnh báo sự dối trá, lén lút hoặc hành động đơn độc.', 'Lương tâm thức tỉnh, thú nhận sai lầm, hoặc vạch trần âm mưu gian lận kịp thời.', 'Kẻ trộm lén lút ôm năm thanh kiếm chuồn khỏi trại lính trong khi hai thanh kiếm vẫn cắm lại sau lưng. Hành vi vụng trộm, sự thiếu minh bạch và chiến thuật né tránh đối đầu trực diện.', 'NO', 'Cảnh báo về sự gian dối, trốn tránh trách nhiệm hoặc những mưu mô thiếu minh bạch phía sau lưng.', '7 tuần hoặc thời điểm bí mật bị phơi bày (khoảng 9/2 - 18/2).', 'assets/cards/swords_07.jpg') ON DUPLICATE KEY UPDATE `name_vi` = VALUES(`name_vi`), `name_en` = VALUES(`name_en`), `arcana_type` = VALUES(`arcana_type`), `suit_element` = VALUES(`suit_element`), `keywords` = VALUES(`keywords`), `upright_meaning` = VALUES(`upright_meaning`), `reversed_meaning` = VALUES(`reversed_meaning`), `archetype_story` = VALUES(`archetype_story`), `yes_no_result` = VALUES(`yes_no_result`), `yes_no_reason` = VALUES(`yes_no_reason`), `time_prediction` = VALUES(`time_prediction`), `image_path` = VALUES(`image_path`);

-- [58/78] swords-8: Eight of Swords (Eight of Swords (Tám Kiếm))
INSERT INTO `TarotCard` (`card_id`, `name_vi`, `name_en`, `arcana_type`, `suit_element`, `keywords`, `upright_meaning`, `reversed_meaning`, `archetype_story`, `yes_no_result`, `yes_no_reason`, `time_prediction`, `image_path`) VALUES ('swords-8', 'Eight of Swords (Tám Kiếm)', 'Eight of Swords', 'Minor', 'Khí', 'Bế tắc tự tạo, Trói buộc tâm lý, Ảo tưởng bất lực, Tìm lối thoát', 'Người phụ nữ bị bịt mắt và trói lỏng lẻo đứng giữa tám thanh kiếm cắm xung quanh trên bãi bùn lầy. Xiềng xích thực chất nằm ở chính nỗi sợ hãi trong tâm trí bạn!', 'Tự cởi trói cho bản thân, mở mắt nhìn thấy lối thoát và dũng cảm bước ra khỏi sự giam cầm.', 'Người phụ nữ bị bịt mắt, trói tay đứng giữa tám thanh kiếm cắm xung quanh trên bãi đất lầy lội. Sự bất lực giả tạo khi tâm trí tự dựng nên rào cản giam cầm chính mình.', 'NO', 'Nhà tù tâm trí do chính nỗi sợ hãi tự thắt chặt; hãy nhận ra sợi dây trói vốn rất lỏng lẻo và tự bước ra.', '8 tuần hoặc giai đoạn cần tự cởi trói tâm lý (Song Tử: 21/5 - 31/5).', 'assets/cards/swords_08.jpg') ON DUPLICATE KEY UPDATE `name_vi` = VALUES(`name_vi`), `name_en` = VALUES(`name_en`), `arcana_type` = VALUES(`arcana_type`), `suit_element` = VALUES(`suit_element`), `keywords` = VALUES(`keywords`), `upright_meaning` = VALUES(`upright_meaning`), `reversed_meaning` = VALUES(`reversed_meaning`), `archetype_story` = VALUES(`archetype_story`), `yes_no_result` = VALUES(`yes_no_result`), `yes_no_reason` = VALUES(`yes_no_reason`), `time_prediction` = VALUES(`time_prediction`), `image_path` = VALUES(`image_path`);

-- [59/78] swords-9: Nine of Swords (Nine of Swords (Chín Kiếm))
INSERT INTO `TarotCard` (`card_id`, `name_vi`, `name_en`, `arcana_type`, `suit_element`, `keywords`, `upright_meaning`, `reversed_meaning`, `archetype_story`, `yes_no_result`, `yes_no_reason`, `time_prediction`, `image_path`) VALUES ('swords-9', 'Nine of Swords (Chín Kiếm)', 'Nine of Swords', 'Minor', 'Khí', 'Mất ngủ lo âu, Cơn ác mộng dằn vặt, Suy nghĩ quá mức, Cần buông lỏng', 'Người ngồi ôm mặt khóc trên giường giữa đêm đen, chín thanh kiếm treo lơ lửng phía trên. Cơn ác mộng của sự âu lo, dằn vặt và nỗi sợ hãi phóng đại quá mức.', 'Ánh bình minh xua tan cơn ác mộng; tìm kiếm sự giúp đỡ tâm lý, nhận ra thực tế không tệ như mình nghĩ.', 'Người ôm mặt khóc than trên giường ngủ giữa đêm đen u tối với chín thanh kiếm treo trên tường đầu giường. Cơn ác mộng nửa đêm, sự ân hận và nỗi dằn vặt tâm can quá mức.', 'NO', 'Cơn ác mộng nửa đêm và nỗi lo lắng bi kịch hóa; thực tế không tồi tệ như tâm trí bạn thêu dệt, hãy bật đèn thức dậy.', '9 tuần hoặc trong những đêm mất ngủ (khoảng 1/6 - 10/6).', 'assets/cards/swords_09.jpg') ON DUPLICATE KEY UPDATE `name_vi` = VALUES(`name_vi`), `name_en` = VALUES(`name_en`), `arcana_type` = VALUES(`arcana_type`), `suit_element` = VALUES(`suit_element`), `keywords` = VALUES(`keywords`), `upright_meaning` = VALUES(`upright_meaning`), `reversed_meaning` = VALUES(`reversed_meaning`), `archetype_story` = VALUES(`archetype_story`), `yes_no_result` = VALUES(`yes_no_result`), `yes_no_reason` = VALUES(`yes_no_reason`), `time_prediction` = VALUES(`time_prediction`), `image_path` = VALUES(`image_path`);

-- [60/78] swords-10: Ten of Swords (Ten of Swords (Mười Kiếm))
INSERT INTO `TarotCard` (`card_id`, `name_vi`, `name_en`, `arcana_type`, `suit_element`, `keywords`, `upright_meaning`, `reversed_meaning`, `archetype_story`, `yes_no_result`, `yes_no_reason`, `time_prediction`, `image_path`) VALUES ('swords-10', 'Ten of Swords (Mười Kiếm)', 'Ten of Swords', 'Minor', 'Khí', 'Chạm đáy nỗi đau, Chấm dứt hoàn toàn, Bình minh sau đêm đen, Không thể tệ hơn', 'Người nằm úp trên bờ biển với mười thanh kiếm cắm trên lưng dưới bầu trời đen kịt. Nhưng nhìn kìa, chân trời phía xa ánh vàng bình minh đang ló rạng. Mọi chuyện không thể tệ hơn được nữa!', 'Sự hồi sinh kỳ diệu từ cõi chết; bắt đầu quá trình chữa lành sau thảm họa tồi tệ nhất.', 'Người đàn ông gục ngã trên bờ biển với mười thanh kiếm đâm dọc sống lưng, nhưng phía chân trời xa mây đen đang tan và ánh bình minh vàng hé lộ. Điểm chạm đáy của đau thương và sự tái sinh.', 'NO', 'Đã chạm đáy nỗi đau cũ; không thể rơi sâu hơn được nữa, chu kỳ cũ đã chết và ánh bình minh tái sinh đang ló rạng.', '10 tuần hoặc thời điểm kết thúc triệt để chu kỳ cũ (khoảng 11/6 - 20/6).', 'assets/cards/swords_10.jpg') ON DUPLICATE KEY UPDATE `name_vi` = VALUES(`name_vi`), `name_en` = VALUES(`name_en`), `arcana_type` = VALUES(`arcana_type`), `suit_element` = VALUES(`suit_element`), `keywords` = VALUES(`keywords`), `upright_meaning` = VALUES(`upright_meaning`), `reversed_meaning` = VALUES(`reversed_meaning`), `archetype_story` = VALUES(`archetype_story`), `yes_no_result` = VALUES(`yes_no_result`), `yes_no_reason` = VALUES(`yes_no_reason`), `time_prediction` = VALUES(`time_prediction`), `image_path` = VALUES(`image_path`);

-- [61/78] swords-11: Page of Swords (Page of Swords (Tiểu Đồng Kiếm))
INSERT INTO `TarotCard` (`card_id`, `name_vi`, `name_en`, `arcana_type`, `suit_element`, `keywords`, `upright_meaning`, `reversed_meaning`, `archetype_story`, `yes_no_result`, `yes_no_reason`, `time_prediction`, `image_path`) VALUES ('swords-11', 'Page of Swords (Tiểu Đồng Kiếm)', 'Page of Swords', 'Minor', 'Khí', 'Hiếu kỳ tò mò, Trí tuệ nhanh nhạy, Cảnh giác thu thập tin tức, Ăn nói sắc bén', 'Chàng trai trẻ cầm kiếm đứng trên gò đất lộng gió, mắt liếc nhìn xung quanh cảnh giác. Trí tò mò cao độ, ham học hỏi và theo dõi tin tức nhạy bén.', 'Nói nhiều làm ít, hay soi mói chuyện người khác, buôn chuyện đưa tin thất thiệt.', 'Chàng trai đứng trên đỉnh đồi lộng gió cầm kiếm giương cao với ánh mắt sắc lạnh cảnh giác. Tinh thần tò mò, trí tuệ sắc sảo, thích khám phá sự thật nhưng cần cẩn trọng lời ăn tiếng nói.', 'MAYBE', 'Tính tò mò, thăm dò thông tin và sự sắc sảo nhưng còn thiếu trải nghiệm thực tế; cần thận trọng phát ngôn.', 'Vài ngày đến 1 tuần hoặc mùa Khí.', 'assets/cards/swords_11.jpg') ON DUPLICATE KEY UPDATE `name_vi` = VALUES(`name_vi`), `name_en` = VALUES(`name_en`), `arcana_type` = VALUES(`arcana_type`), `suit_element` = VALUES(`suit_element`), `keywords` = VALUES(`keywords`), `upright_meaning` = VALUES(`upright_meaning`), `reversed_meaning` = VALUES(`reversed_meaning`), `archetype_story` = VALUES(`archetype_story`), `yes_no_result` = VALUES(`yes_no_result`), `yes_no_reason` = VALUES(`yes_no_reason`), `time_prediction` = VALUES(`time_prediction`), `image_path` = VALUES(`image_path`);

-- [62/78] swords-12: Knight of Swords (Knight of Swords (Hiệp Sĩ Kiếm))
INSERT INTO `TarotCard` (`card_id`, `name_vi`, `name_en`, `arcana_type`, `suit_element`, `keywords`, `upright_meaning`, `reversed_meaning`, `archetype_story`, `yes_no_result`, `yes_no_reason`, `time_prediction`, `image_path`) VALUES ('swords-12', 'Knight of Swords (Hiệp Sĩ Kiếm)', 'Knight of Swords', 'Minor', 'Khí', 'Lao về phía trước, Quyết liệt thẳng thắn, Tư duy thần tốc, Không khoan nhượng', 'Kỵ sĩ vung kiếm thúc ngựa phi như bay giữa cơn bão táp. Hành động quyết liệt, tư duy sắc bén như dao và không ngại va chạm để đạt mục tiêu.', 'Hung hăng, nóng nảy, nói năng xúc phạm người khác, hành động bất chấp hậu quả.', 'Kỵ sĩ cưỡi ngựa chiến phi như gió lốc giữa bầu trời mây rách, vung kiếm lao thẳng vào kẻ thù. Đại diện cho sự quyết liệt, thông minh vượt trội nhưng dễ rơi vào hiếu chiến và tàn nhẫn.', 'MAYBE', 'Tốc độ lao đi như bão táp nhưng quá nóng nảy và thiếu suy tính; cẩn thận va chạm gây tổn thương đôi bên.', 'Cực kỳ nhanh chóng trong vài ngày tới.', 'assets/cards/swords_12.jpg') ON DUPLICATE KEY UPDATE `name_vi` = VALUES(`name_vi`), `name_en` = VALUES(`name_en`), `arcana_type` = VALUES(`arcana_type`), `suit_element` = VALUES(`suit_element`), `keywords` = VALUES(`keywords`), `upright_meaning` = VALUES(`upright_meaning`), `reversed_meaning` = VALUES(`reversed_meaning`), `archetype_story` = VALUES(`archetype_story`), `yes_no_result` = VALUES(`yes_no_result`), `yes_no_reason` = VALUES(`yes_no_reason`), `time_prediction` = VALUES(`time_prediction`), `image_path` = VALUES(`image_path`);

-- [63/78] swords-13: Queen of Swords (Queen of Swords (Hoàng Hậu Kiếm))
INSERT INTO `TarotCard` (`card_id`, `name_vi`, `name_en`, `arcana_type`, `suit_element`, `keywords`, `upright_meaning`, `reversed_meaning`, `archetype_story`, `yes_no_result`, `yes_no_reason`, `time_prediction`, `image_path`) VALUES ('swords-13', 'Queen of Swords (Hoàng Hậu Kiếm)', 'Queen of Swords', 'Minor', 'Khí', 'Lý trí sắc sảo, Độc lập tự chủ, Minh bạch công tâm, Kinh nghiệm từng trải', 'Người phụ nữ ngồi thẳng trên ngai vàng giơ cao thanh kiếm, tay kia giang ra đón nhận sự thật. Bà là hiện thân của trí tuệ sắc bén, sự độc lập và không khoan nhượng với dối trá.', 'Cay nghiệt, lạnh lùng tàn nhẫn, luôn phán xét người khác và mang nặng hận thù trong lòng.', 'Hoàng hậu ngồi trên ngai vàng khắc hình bướm và thiên thần, một tay cầm kiếm thẳng đứng, một tay đưa ra phía trước. Sự sáng suốt, từng trải qua đau thương để đạt được lý trí thép và sự độc lập.', 'YES', 'Lý trí sắc bén như dao cạo, phân định đúng sai công tâm và sự độc lập kiên cường giúp bạn vượt qua sóng gió.', 'Khoảng 1 tháng hoặc mùa thu se lạnh.', 'assets/cards/swords_13.jpg') ON DUPLICATE KEY UPDATE `name_vi` = VALUES(`name_vi`), `name_en` = VALUES(`name_en`), `arcana_type` = VALUES(`arcana_type`), `suit_element` = VALUES(`suit_element`), `keywords` = VALUES(`keywords`), `upright_meaning` = VALUES(`upright_meaning`), `reversed_meaning` = VALUES(`reversed_meaning`), `archetype_story` = VALUES(`archetype_story`), `yes_no_result` = VALUES(`yes_no_result`), `yes_no_reason` = VALUES(`yes_no_reason`), `time_prediction` = VALUES(`time_prediction`), `image_path` = VALUES(`image_path`);

-- [64/78] swords-14: King of Swords (King of Swords (Vua Kiếm))
INSERT INTO `TarotCard` (`card_id`, `name_vi`, `name_en`, `arcana_type`, `suit_element`, `keywords`, `upright_meaning`, `reversed_meaning`, `archetype_story`, `yes_no_result`, `yes_no_reason`, `time_prediction`, `image_path`) VALUES ('swords-14', 'King of Swords (Vua Kiếm)', 'King of Swords', 'Minor', 'Khí', 'Quyền uy trí tuệ, Chân lý tối thượng, Phán quyết công minh, Kỷ luật thép', 'Vị vua quyền uy cầm kiếm ngồi trên ngai vàng giữa bầu trời trong vắt. Đại diện cho đỉnh cao của trí tuệ, sự công bằng tuyệt đối và khả năng phán đoán chính xác.', 'Bạo chúa dùng trí thông minh để thao túng luật lệ, tàn nhẫn và độc đoán không chút tình người.', 'Vị vua ngồi trên ngai cao giữa bầu trời trong vắt, tay cầm gươm báu công lý với ánh nhìn uy nghiêm thấu suốt tâm can. Bậc thầy tư duy phân tích, quy chuẩn luật lệ và sự thật tối thượng.', 'YES', 'Bậc thầy tư duy chiến lược, sự thật khách quan và uy tín lãnh đạo bằng công lý đưa ra kết luận chuẩn xác.', 'Khoảng 1 - 2 tháng hoặc mùa đông lập thu.', 'assets/cards/swords_14.jpg') ON DUPLICATE KEY UPDATE `name_vi` = VALUES(`name_vi`), `name_en` = VALUES(`name_en`), `arcana_type` = VALUES(`arcana_type`), `suit_element` = VALUES(`suit_element`), `keywords` = VALUES(`keywords`), `upright_meaning` = VALUES(`upright_meaning`), `reversed_meaning` = VALUES(`reversed_meaning`), `archetype_story` = VALUES(`archetype_story`), `yes_no_result` = VALUES(`yes_no_result`), `yes_no_reason` = VALUES(`yes_no_reason`), `time_prediction` = VALUES(`time_prediction`), `image_path` = VALUES(`image_path`);

-- [65/78] pentacles-1: Ace of Pentacles (Ace of Pentacles (Ách Tiền))
INSERT INTO `TarotCard` (`card_id`, `name_vi`, `name_en`, `arcana_type`, `suit_element`, `keywords`, `upright_meaning`, `reversed_meaning`, `archetype_story`, `yes_no_result`, `yes_no_reason`, `time_prediction`, `image_path`) VALUES ('pentacles-1', 'Ace of Pentacles (Ách Tiền)', 'Ace of Pentacles', 'Minor', 'Đất', 'Cơ hội tài lộc, Hạt mầm thịnh vượng, Thành quả cụ thể, Nền tảng vững chắc', 'Bàn tay từ mây chìa ra đồng tiền vàng khổng lồ lơ lửng trên khu vườn hoa nở rộ. Cơ hội vàng về tài chính, công việc mới và sự khởi sắc về của cải.', 'Bỏ lỡ cơ hội làm giàu, chi tiêu vượt quá ngân sách, hoặc kế hoạch đầu tư thiếu tính khả thi.', 'Bàn tay vũ trụ chìa đồng tiền vàng lấp lánh ra từ đám mây trên khu vườn sum suê hoa cỏ dẫn lối qua cổng vòm. Hạt mầm vật chất màu mỡ, cơ hội đầu tư tài chính và phước lành thực tế.', 'YES', 'Hạt mầm tài chính, cơ hội đầu tư và sự thịnh vượng thực tế đang được vũ trụ trao tận tay bạn; hãy đón nhận.', '1 năm hoặc mùa đông (Ma Kết).', 'assets/cards/pentacles_01.jpg') ON DUPLICATE KEY UPDATE `name_vi` = VALUES(`name_vi`), `name_en` = VALUES(`name_en`), `arcana_type` = VALUES(`arcana_type`), `suit_element` = VALUES(`suit_element`), `keywords` = VALUES(`keywords`), `upright_meaning` = VALUES(`upright_meaning`), `reversed_meaning` = VALUES(`reversed_meaning`), `archetype_story` = VALUES(`archetype_story`), `yes_no_result` = VALUES(`yes_no_result`), `yes_no_reason` = VALUES(`yes_no_reason`), `time_prediction` = VALUES(`time_prediction`), `image_path` = VALUES(`image_path`);

-- [66/78] pentacles-2: Two of Pentacles (Two of Pentacles (Hai Tiền))
INSERT INTO `TarotCard` (`card_id`, `name_vi`, `name_en`, `arcana_type`, `suit_element`, `keywords`, `upright_meaning`, `reversed_meaning`, `archetype_story`, `yes_no_result`, `yes_no_reason`, `time_prediction`, `image_path`) VALUES ('pentacles-2', 'Two of Pentacles (Hai Tiền)', 'Two of Pentacles', 'Minor', 'Đất', 'Tung hứng linh hoạt, Cân bằng tài chính, Thích nghi hoàn cảnh, Dòng tiền xoay vần', 'Chàng trai vừa nhảy múa vừa tung hứng hai đồng tiền vàng trong vòng vô cực bên bờ biển sóng dập dồn. Khả năng xoay xở linh hoạt với nhiều nguồn lực cùng lúc.', 'Quá tải tài chính, mất cân bằng thu chi, xoay xở không kịp dẫn đến nợ nần chồng chất.', 'Chàng trai nhún nhảy trên bờ biển tung hứng hai đồng tiền vàng trong vòng vô cực (Lemniscate) trong khi tàu bè chao đảo trên sóng dữ. Khả năng thích ứng linh hoạt và giữ thăng bằng giữa biến động.', 'MAYBE', 'Bạn đang tung hứng giữa hai dòng tiền hoặc hai trách nhiệm; cần linh hoạt thích ứng giữ thăng bằng thay vì phân tâm.', '2 năm hoặc giai đoạn biến động tài chính ngắn hạn (khoảng 22/12 - 31/12).', 'assets/cards/pentacles_02.jpg') ON DUPLICATE KEY UPDATE `name_vi` = VALUES(`name_vi`), `name_en` = VALUES(`name_en`), `arcana_type` = VALUES(`arcana_type`), `suit_element` = VALUES(`suit_element`), `keywords` = VALUES(`keywords`), `upright_meaning` = VALUES(`upright_meaning`), `reversed_meaning` = VALUES(`reversed_meaning`), `archetype_story` = VALUES(`archetype_story`), `yes_no_result` = VALUES(`yes_no_result`), `yes_no_reason` = VALUES(`yes_no_reason`), `time_prediction` = VALUES(`time_prediction`), `image_path` = VALUES(`image_path`);

-- [67/78] pentacles-3: Three of Pentacles (Three of Pentacles (Ba Tiền))
INSERT INTO `TarotCard` (`card_id`, `name_vi`, `name_en`, `arcana_type`, `suit_element`, `keywords`, `upright_meaning`, `reversed_meaning`, `archetype_story`, `yes_no_result`, `yes_no_reason`, `time_prediction`, `image_path`) VALUES ('pentacles-3', 'Three of Pentacles (Ba Tiền)', 'Three of Pentacles', 'Minor', 'Đất', 'Làm việc nhóm ăn ý, Tay nghề bậc thầy, Xây dựng công trình, Được công nhận kỹ năng', 'Người thợ điêu khắc trẻ đang bàn bạc bản thiết kế nhà thờ cùng một tu sĩ và kiến trúc sư. Tinh thần hợp tác nhóm tuyệt vời, kỹ năng chuyên môn được đánh giá cao.', 'Làm việc nhóm rời rạc, bất đồng quan điểm chuyên môn, tay nghề kém cỏi gây hỏng việc.', 'Người thợ điêu khắc chăm chú hoàn thiện thánh đường dưới sự bàn bạc của nhà sư và kiến trúc sư cầm bản vẽ. Tinh thần hợp tác chuyên môn, rèn luyện tay nghề bậc thầy và xây dựng công trình vĩ đại.', 'YES', 'Sự hợp tác nhóm ăn ý, tay nghề chuyên môn cao được công nhận và công trình xây dựng đạt chuẩn mực vững bền.', '3 năm hoặc mùa xuân/thu hoạch công trình (khoảng 1/1 - 10/1).', 'assets/cards/pentacles_03.jpg') ON DUPLICATE KEY UPDATE `name_vi` = VALUES(`name_vi`), `name_en` = VALUES(`name_en`), `arcana_type` = VALUES(`arcana_type`), `suit_element` = VALUES(`suit_element`), `keywords` = VALUES(`keywords`), `upright_meaning` = VALUES(`upright_meaning`), `reversed_meaning` = VALUES(`reversed_meaning`), `archetype_story` = VALUES(`archetype_story`), `yes_no_result` = VALUES(`yes_no_result`), `yes_no_reason` = VALUES(`yes_no_reason`), `time_prediction` = VALUES(`time_prediction`), `image_path` = VALUES(`image_path`);

-- [68/78] pentacles-4: Four of Pentacles (Four of Pentacles (Bốn Tiền))
INSERT INTO `TarotCard` (`card_id`, `name_vi`, `name_en`, `arcana_type`, `suit_element`, `keywords`, `upright_meaning`, `reversed_meaning`, `archetype_story`, `yes_no_result`, `yes_no_reason`, `time_prediction`, `image_path`) VALUES ('pentacles-4', 'Four of Pentacles (Bốn Tiền)', 'Four of Pentacles', 'Minor', 'Đất', 'Giữ của khư khư, Kiểm soát an toàn, Bảo thủ keo kiệt, Nỗi sợ mất mát', 'Người đàn ông ôm chặt đồng tiền trước ngực, hai chân dẫm lên hai đồng và một đồng đội trên đầu. Cảm giác bất an khiến bạn giữ khư khư tài sản và sợ hãi thay đổi.', 'Học cách buông bỏ bớt kiểm soát, mở hầu bao chi tiêu hào phóng hơn, hoặc nguy cơ mất của vì sơ suất.', 'Người đàn ông ngồi ôm chặt đồng tiền trước ngực, hai đồng tiền dưới chân và một đồng trên vương miện, phía sau là thành phố sầm uất. Nỗi sợ mất mát của cải dẫn đến sự bo bo giữ của và bế tắc.', 'MAYBE', 'Bám víu quá mức vào tiền bạc và an toàn ảo giác; sự keo kiệt sẽ chặn đứng dòng chảy thịnh vượng mới.', '4 năm hoặc giai đoạn tích lũy phòng thủ (khoảng 11/1 - 19/1).', 'assets/cards/pentacles_04.jpg') ON DUPLICATE KEY UPDATE `name_vi` = VALUES(`name_vi`), `name_en` = VALUES(`name_en`), `arcana_type` = VALUES(`arcana_type`), `suit_element` = VALUES(`suit_element`), `keywords` = VALUES(`keywords`), `upright_meaning` = VALUES(`upright_meaning`), `reversed_meaning` = VALUES(`reversed_meaning`), `archetype_story` = VALUES(`archetype_story`), `yes_no_result` = VALUES(`yes_no_result`), `yes_no_reason` = VALUES(`yes_no_reason`), `time_prediction` = VALUES(`time_prediction`), `image_path` = VALUES(`image_path`);

-- [69/78] pentacles-5: Five of Pentacles (Five of Pentacles (Năm Tiền))
INSERT INTO `TarotCard` (`card_id`, `name_vi`, `name_en`, `arcana_type`, `suit_element`, `keywords`, `upright_meaning`, `reversed_meaning`, `archetype_story`, `yes_no_result`, `yes_no_reason`, `time_prediction`, `image_path`) VALUES ('pentacles-5', 'Five of Pentacles (Năm Tiền)', 'Five of Pentacles', 'Minor', 'Đất', 'Khó khăn thiếu thốn, Cảm giác bị bỏ rơi, Tổn thương thể xác, Ánh sáng nhà thờ', 'Hai người ăn xin tàn tật lê bước trong tuyết lạnh ngoài ô cửa sổ kính màu ấm áp của nhà thờ. Giai đoạn khó khăn về vật chất, cảm giác cô đơn và bị bỏ rơi.', 'Vượt qua cơn bĩ cực, tìm thấy nơi nương tựa ấm áp, tài chính dần phục hồi sau khủng hoảng.', 'Hai kẻ hành khất tàn tật lầm lũi bước qua bão tuyết bên ngoài cửa sổ kính màu ấm áp của thánh đường. Cảm giác bị bỏ rơi, nghèo đói và mù quáng không nhận ra sự giúp đỡ ngay bên cạnh.', 'NO', 'Cảm giác thiếu thốn, cô độc trong đêm đông giá rét; hãy nhìn lên cửa sổ thánh đường ấm áp đón nhận sự trợ giúp.', '5 năm hoặc đỉnh điểm mùa đông giá rét (Kim Ngưu: 20/4 - 30/4).', 'assets/cards/pentacles_05.jpg') ON DUPLICATE KEY UPDATE `name_vi` = VALUES(`name_vi`), `name_en` = VALUES(`name_en`), `arcana_type` = VALUES(`arcana_type`), `suit_element` = VALUES(`suit_element`), `keywords` = VALUES(`keywords`), `upright_meaning` = VALUES(`upright_meaning`), `reversed_meaning` = VALUES(`reversed_meaning`), `archetype_story` = VALUES(`archetype_story`), `yes_no_result` = VALUES(`yes_no_result`), `yes_no_reason` = VALUES(`yes_no_reason`), `time_prediction` = VALUES(`time_prediction`), `image_path` = VALUES(`image_path`);

-- [70/78] pentacles-6: Six of Pentacles (Six of Pentacles (Sáu Tiền))
INSERT INTO `TarotCard` (`card_id`, `name_vi`, `name_en`, `arcana_type`, `suit_element`, `keywords`, `upright_meaning`, `reversed_meaning`, `archetype_story`, `yes_no_result`, `yes_no_reason`, `time_prediction`, `image_path`) VALUES ('pentacles-6', 'Six of Pentacles (Sáu Tiền)', 'Six of Pentacles', 'Minor', 'Đất', 'Hào phóng sẻ chia, Cân bằng cho và nhận, Nhận được tài trợ, Lòng từ thiện', 'Thương gia giàu có cầm cán cân công lý một tay ban phát tiền vàng cho hai người nghèo khó. Sự hào phóng, sẻ chia phúc lành và cán cân cân bằng giữa cho và nhận.', 'Bố thí với thái độ kẻ cả ban ơn, cho vay tiền nhưng bị quỵt, hoặc nợ nần vì quá hào phóng.', 'Thương nhân giàu có cầm chiếc cân công lý ban phát tiền bạc cho hai người khốn khó dưới chân. Quy luật lưu thông của tiền bạc, sự hào phóng chính trực và luật nhân quả về vật chất.', 'YES', 'Dòng chảy cho và nhận hào phóng, sự bảo trợ từ quý nhân và sự cân bằng tài chính công bằng.', '6 năm hoặc thời điểm nhận được khoản hỗ trợ/thưởng (khoảng 1/5 - 10/5).', 'assets/cards/pentacles_06.jpg') ON DUPLICATE KEY UPDATE `name_vi` = VALUES(`name_vi`), `name_en` = VALUES(`name_en`), `arcana_type` = VALUES(`arcana_type`), `suit_element` = VALUES(`suit_element`), `keywords` = VALUES(`keywords`), `upright_meaning` = VALUES(`upright_meaning`), `reversed_meaning` = VALUES(`reversed_meaning`), `archetype_story` = VALUES(`archetype_story`), `yes_no_result` = VALUES(`yes_no_result`), `yes_no_reason` = VALUES(`yes_no_reason`), `time_prediction` = VALUES(`time_prediction`), `image_path` = VALUES(`image_path`);

-- [71/78] pentacles-7: Seven of Pentacles (Seven of Pentacles (Bảy Tiền))
INSERT INTO `TarotCard` (`card_id`, `name_vi`, `name_en`, `arcana_type`, `suit_element`, `keywords`, `upright_meaning`, `reversed_meaning`, `archetype_story`, `yes_no_result`, `yes_no_reason`, `time_prediction`, `image_path`) VALUES ('pentacles-7', 'Seven of Pentacles (Bảy Tiền)', 'Seven of Pentacles', 'Minor', 'Đất', 'Chờ đợi mùa màng, Đánh giá kết quả, Kiên nhẫn nuôi dưỡng, Đầu tư đường dài', 'Người nông dân chống cuốc đứng ngắm nhìn giàn nho đã đơm bảy đồng tiền vàng trĩu quả. Giai đoạn kiên nhẫn chờ đợi thành quả sau chuỗi ngày lao động miệt mài.', 'Sốt ruột muốn hái quả non, nản lòng vì kết quả đến quá chậm, hoặc đầu tư công sức vào mảnh đất cằn cỗi.', 'Người nông dân dừng cuốc ngắm nhìn giàn nho trĩu bảy đồng tiền vàng với ánh mắt trầm tư. Giai đoạn kiên nhẫn chờ đợi hạt giống sinh sôi, đánh giá tiến độ trước mùa gặt lớn.', 'MAYBE', 'Thời điểm dừng tay đánh giá lại thành quả lao động; kiên nhẫn chờ quả chín, không nên vội vã hái non.', '7 năm hoặc mùa thu hoạch sau chuỗi ngày vun xới (khoảng 11/5 - 20/5).', 'assets/cards/pentacles_07.jpg') ON DUPLICATE KEY UPDATE `name_vi` = VALUES(`name_vi`), `name_en` = VALUES(`name_en`), `arcana_type` = VALUES(`arcana_type`), `suit_element` = VALUES(`suit_element`), `keywords` = VALUES(`keywords`), `upright_meaning` = VALUES(`upright_meaning`), `reversed_meaning` = VALUES(`reversed_meaning`), `archetype_story` = VALUES(`archetype_story`), `yes_no_result` = VALUES(`yes_no_result`), `yes_no_reason` = VALUES(`yes_no_reason`), `time_prediction` = VALUES(`time_prediction`), `image_path` = VALUES(`image_path`);

-- [72/78] pentacles-8: Eight of Pentacles (Eight of Pentacles (Tám Tiền))
INSERT INTO `TarotCard` (`card_id`, `name_vi`, `name_en`, `arcana_type`, `suit_element`, `keywords`, `upright_meaning`, `reversed_meaning`, `archetype_story`, `yes_no_result`, `yes_no_reason`, `time_prediction`, `image_path`) VALUES ('pentacles-8', 'Eight of Pentacles (Tám Tiền)', 'Eight of Pentacles', 'Minor', 'Đất', 'Cần cù tỉ mỉ, Rèn luyện tay nghề, Tập trung chuyên môn, Chăm chỉ hoàn thiện', 'Người thợ thủ công cần mẫn ngồi gõ từng đồng tiền vàng với sự tập trung tuyệt đối. Tinh thần lao động hăng say, rèn luyện kỹ năng bậc thầy và chăm chút từng chi tiết.', 'Làm việc cẩu thả qua loa, chán nản vì công việc lặp đi lặp lại tẻ nhạt, hoặc nghiện việc quá mức.', 'Người thợ thủ công trẻ tuổi cần mẫn ngồi đục chạm từng đồng tiền vàng treo thành hàng ngay ngắn trên cột gỗ. Sự kỷ luật thép, tinh thần cầu toàn rèn giũa kỹ năng và đạo đức nghề nghiệp.', 'YES', 'Sự cần mẫn mài giũa kỹ năng, chăm chỉ học nghề từng ngày sẽ xây đắp thành công bậc thầy vững chãi.', '8 năm hoặc quá trình rèn luyện tính bằng nhiều tháng/năm (Xử Nữ: 23/8 - 1/9).', 'assets/cards/pentacles_08.jpg') ON DUPLICATE KEY UPDATE `name_vi` = VALUES(`name_vi`), `name_en` = VALUES(`name_en`), `arcana_type` = VALUES(`arcana_type`), `suit_element` = VALUES(`suit_element`), `keywords` = VALUES(`keywords`), `upright_meaning` = VALUES(`upright_meaning`), `reversed_meaning` = VALUES(`reversed_meaning`), `archetype_story` = VALUES(`archetype_story`), `yes_no_result` = VALUES(`yes_no_result`), `yes_no_reason` = VALUES(`yes_no_reason`), `time_prediction` = VALUES(`time_prediction`), `image_path` = VALUES(`image_path`);

-- [73/78] pentacles-9: Nine of Pentacles (Nine of Pentacles (Chín Tiền))
INSERT INTO `TarotCard` (`card_id`, `name_vi`, `name_en`, `arcana_type`, `suit_element`, `keywords`, `upright_meaning`, `reversed_meaning`, `archetype_story`, `yes_no_result`, `yes_no_reason`, `time_prediction`, `image_path`) VALUES ('pentacles-9', 'Nine of Pentacles (Chín Tiền)', 'Nine of Pentacles', 'Minor', 'Đất', 'Độc lập giàu có, Tận hưởng thành quả, Phong thái quý phái, Tự do tài chính', 'Quý bà thanh lịch dạo bước trong vườn nho trĩu quả với chú chim ưng trên tay. Tự do tài chính, độc lập tự chủ và tận hưởng cuộc sống xa hoa do chính tay mình tạo dựng.', 'Phụ thuộc tài chính vào người khác, khoe mẽ giàu sang ảo, hoặc cô đơn trên đống tài sản.', 'Quý bà thanh lịch dạo bước trong vườn nho trĩu quả với chú chim ưng đậu trên tay và chú ốc sên dưới chân. Đỉnh cao của sự độc lập tự chủ, thành tựu tài chính cá nhân và cuộc sống an nhàn quý phái.', 'YES', 'Tự do tài chính, độc lập tự chủ và phong thái quý phái tận hưởng khu vườn thành quả của chính mình.', '9 năm hoặc mùa thu hoạch thịnh vượng (khoảng 2/9 - 11/9).', 'assets/cards/pentacles_09.jpg') ON DUPLICATE KEY UPDATE `name_vi` = VALUES(`name_vi`), `name_en` = VALUES(`name_en`), `arcana_type` = VALUES(`arcana_type`), `suit_element` = VALUES(`suit_element`), `keywords` = VALUES(`keywords`), `upright_meaning` = VALUES(`upright_meaning`), `reversed_meaning` = VALUES(`reversed_meaning`), `archetype_story` = VALUES(`archetype_story`), `yes_no_result` = VALUES(`yes_no_result`), `yes_no_reason` = VALUES(`yes_no_reason`), `time_prediction` = VALUES(`time_prediction`), `image_path` = VALUES(`image_path`);

-- [74/78] pentacles-10: Ten of Pentacles (Ten of Pentacles (Mười Tiền))
INSERT INTO `TarotCard` (`card_id`, `name_vi`, `name_en`, `arcana_type`, `suit_element`, `keywords`, `upright_meaning`, `reversed_meaning`, `archetype_story`, `yes_no_result`, `yes_no_reason`, `time_prediction`, `image_path`) VALUES ('pentacles-10', 'Ten of Pentacles (Mười Tiền)', 'Ten of Pentacles', 'Minor', 'Đất', 'Gia tộc thịnh vượng, Thừa kế gia sản, Nền móng bền vững, Viên mãn nhiều đời', 'Đại gia đình nhiều thế hệ sum vầy trước cổng dinh thự cổ kính cùng hai chú chó cưng, mười đồng tiền vàng kết thành cây sự sống. Thịnh vượng dài lâu và gia đình giàu có viên mãn.', 'Tranh chấp tài sản thừa kế trong dòng họ, công việc kinh doanh gia đình gặp rủi ro, hoặc truyền thống gò bó.', 'Ba thế hệ gia tộc sum vầy trước cổng dinh thự cổ kính cùng hai chú chó cưng dưới vòm cây sự sống kết bằng mười đồng tiền vàng. Sự hưng thịnh vững bền của gia tộc và di sản truyền đời.', 'YES', 'Gia tộc hưng vượng, nền móng vững chắc qua nhiều thế hệ và di sản vật chất viên mãn dài lâu.', '10 năm hoặc mục tiêu lâu dài nhiều thế hệ (khoảng 12/9 - 22/9).', 'assets/cards/pentacles_10.jpg') ON DUPLICATE KEY UPDATE `name_vi` = VALUES(`name_vi`), `name_en` = VALUES(`name_en`), `arcana_type` = VALUES(`arcana_type`), `suit_element` = VALUES(`suit_element`), `keywords` = VALUES(`keywords`), `upright_meaning` = VALUES(`upright_meaning`), `reversed_meaning` = VALUES(`reversed_meaning`), `archetype_story` = VALUES(`archetype_story`), `yes_no_result` = VALUES(`yes_no_result`), `yes_no_reason` = VALUES(`yes_no_reason`), `time_prediction` = VALUES(`time_prediction`), `image_path` = VALUES(`image_path`);

-- [75/78] pentacles-11: Page of Pentacles (Page of Pentacles (Tiểu Đồng Tiền))
INSERT INTO `TarotCard` (`card_id`, `name_vi`, `name_en`, `arcana_type`, `suit_element`, `keywords`, `upright_meaning`, `reversed_meaning`, `archetype_story`, `yes_no_result`, `yes_no_reason`, `time_prediction`, `image_path`) VALUES ('pentacles-11', 'Page of Pentacles (Tiểu Đồng Tiền)', 'Page of Pentacles', 'Minor', 'Đất', 'Khát khao học hỏi, Cơ hội thực tế, Học nghề chăm chỉ, Tin tức tài chính tốt', 'Chàng trai trẻ chăm chú nâng niu đồng tiền vàng giữa cánh đồng xanh mướt. Tinh thần học hỏi thực tế, chăm chỉ học nghề và nhận được tin vui về công việc hoặc tiền bạc.', 'Lười biếng, thiếu tập trung, lãng phí cơ hội học tập thực tế, chi tiêu tiền bạc thiếu suy nghĩ.', 'Chàng thiếu niên chăm chú nâng niu đồng tiền vàng giữa cánh đồng xanh mướt dưới trời quang đãng. Tinh thần học nghề thực tế, tính cẩn trọng và khát khao tích lũy tri thức ứng dụng.', 'YES', 'Khát khao học hỏi thực tế, sự chăm chỉ tích lũy và tin vui khởi sắc về công việc/tiền bạc.', 'Vài tuần đến vài tháng hoặc mùa Đất.', 'assets/cards/pentacles_11.jpg') ON DUPLICATE KEY UPDATE `name_vi` = VALUES(`name_vi`), `name_en` = VALUES(`name_en`), `arcana_type` = VALUES(`arcana_type`), `suit_element` = VALUES(`suit_element`), `keywords` = VALUES(`keywords`), `upright_meaning` = VALUES(`upright_meaning`), `reversed_meaning` = VALUES(`reversed_meaning`), `archetype_story` = VALUES(`archetype_story`), `yes_no_result` = VALUES(`yes_no_result`), `yes_no_reason` = VALUES(`yes_no_reason`), `time_prediction` = VALUES(`time_prediction`), `image_path` = VALUES(`image_path`);

-- [76/78] pentacles-12: Knight of Pentacles (Knight of Pentacles (Hiệp Sĩ Tiền))
INSERT INTO `TarotCard` (`card_id`, `name_vi`, `name_en`, `arcana_type`, `suit_element`, `keywords`, `upright_meaning`, `reversed_meaning`, `archetype_story`, `yes_no_result`, `yes_no_reason`, `time_prediction`, `image_path`) VALUES ('pentacles-12', 'Knight of Pentacles (Hiệp Sĩ Tiền)', 'Knight of Pentacles', 'Minor', 'Đất', 'Bền bỉ kiên định, Chăm chỉ đáng tin, Trách nhiệm chu đáo, Chậm mà chắc', 'Kỵ sĩ ngồi trên lưng ngựa đen đứng vững chãi trên cánh đồng cày xới, tay cầm đồng tiền vàng với sự cẩn trọng tuyệt đối. Biểu tượng của sự kiên định, chậm mà chắc và đáng tin cậy bậc nhất.', 'Bảo thủ cứng nhắc, lười biếng ì ạch, chán ngắt trong cuộc sống thường nhật, sợ hãi thay đổi.', 'Kỵ sĩ ngồi trên lưng chiến mã đen đứng trầm mặc giữa cánh đồng cày xới, tay cầm đồng tiền với sự kiên định tối thượng. Đại diện cho sự bền bỉ phi thường, phương châm chậm mà chắc và sự trung thành tuyệt đối.', 'YES', 'Chậm mà chắc, tính kiên định và trách nhiệm chu đáo tuyệt đối; thành quả bền vững như bàn thạch.', 'Diễn tiến chậm rãi trong vài tháng đến 1 năm.', 'assets/cards/pentacles_12.jpg') ON DUPLICATE KEY UPDATE `name_vi` = VALUES(`name_vi`), `name_en` = VALUES(`name_en`), `arcana_type` = VALUES(`arcana_type`), `suit_element` = VALUES(`suit_element`), `keywords` = VALUES(`keywords`), `upright_meaning` = VALUES(`upright_meaning`), `reversed_meaning` = VALUES(`reversed_meaning`), `archetype_story` = VALUES(`archetype_story`), `yes_no_result` = VALUES(`yes_no_result`), `yes_no_reason` = VALUES(`yes_no_reason`), `time_prediction` = VALUES(`time_prediction`), `image_path` = VALUES(`image_path`);

-- [77/78] pentacles-13: Queen of Pentacles (Queen of Pentacles (Hoàng Hậu Tiền))
INSERT INTO `TarotCard` (`card_id`, `name_vi`, `name_en`, `arcana_type`, `suit_element`, `keywords`, `upright_meaning`, `reversed_meaning`, `archetype_story`, `yes_no_result`, `yes_no_reason`, `time_prediction`, `image_path`) VALUES ('pentacles-13', 'Queen of Pentacles (Hoàng Hậu Tiền)', 'Queen of Pentacles', 'Minor', 'Đất', 'Người mẹ nuôi dưỡng, Đảm đang khéo léo, Thực tế ấm áp, Thịnh vượng an vui', 'Hoàng hậu ngồi trên ngai vàng trạm trổ giữa thiên nhiên xanh tốt ôm đồng tiền vàng với ánh mắt trìu mến. Người phụ nữ đảm đang, biết quản lý tài chính và chăm sóc gia đình chu đáo ấm êm.', 'Bỏ bê bản thân, lo lắng thái quá về tiền bạc, hoặc dùng vật chất để kiểm soát tình cảm gia đình.', 'Hoàng hậu ngồi trên ngai vàng trạm trổ giữa cỏ hoa sum suê ôm đồng tiền vàng với tình thương bao la, bên cạnh là chú thỏ hoang dã. Biểu tượng của người phụ nữ đảm đang, thịnh vượng và nuôi dưỡng gia đình sung túc.', 'YES', 'Người mẹ đảm đang nuôi dưỡng, quản lý tài chính khéo léo và mang lại sự sung túc ấm êm cho tổ ấm.', 'Khoảng vài tháng đến 1 năm hoặc mùa đông ấm áp.', 'assets/cards/pentacles_13.jpg') ON DUPLICATE KEY UPDATE `name_vi` = VALUES(`name_vi`), `name_en` = VALUES(`name_en`), `arcana_type` = VALUES(`arcana_type`), `suit_element` = VALUES(`suit_element`), `keywords` = VALUES(`keywords`), `upright_meaning` = VALUES(`upright_meaning`), `reversed_meaning` = VALUES(`reversed_meaning`), `archetype_story` = VALUES(`archetype_story`), `yes_no_result` = VALUES(`yes_no_result`), `yes_no_reason` = VALUES(`yes_no_reason`), `time_prediction` = VALUES(`time_prediction`), `image_path` = VALUES(`image_path`);

-- [78/78] pentacles-14: King of Pentacles (King of Pentacles (Vua Tiền))
INSERT INTO `TarotCard` (`card_id`, `name_vi`, `name_en`, `arcana_type`, `suit_element`, `keywords`, `upright_meaning`, `reversed_meaning`, `archetype_story`, `yes_no_result`, `yes_no_reason`, `time_prediction`, `image_path`) VALUES ('pentacles-14', 'King of Pentacles (Vua Tiền)', 'King of Pentacles', 'Minor', 'Đất', 'Đế chế tài chính, Bậc thầy thịnh vượng, Đáng tin cậy vững chãi, Thành công vật chất', 'Vị vua ngồi trên ngai vàng khắc hình đầu bò đực giữa lâu đài nguy nga và vườn nho sum suê. Đỉnh cao của sự thành đạt, giàu có, uy tín vững chắc và bản lĩnh làm chủ đồng tiền.', 'Thực dụng đến tàn nhẫn, hám lợi bất chấp đạo đức, tham nhũng hoặc phá sản vì đầu tư liều lĩnh.', 'Vị vua ngồi trên ngai khắc hình đầu bò đực giữa lâu đài nguy nga và vườn nho vàng óng, áo choàng thêu chùm nho trù phú. Bậc thầy làm chủ vật chất, đỉnh cao thành đạt kinh doanh và sự thịnh vượng vững chắc.', 'YES', 'Đế chế tài chính hùng mạnh, bậc thầy làm chủ đồng tiền và uy tín kinh doanh vững chãi tối thượng.', 'Khoảng 1 năm hoặc thời điểm chốt sổ gặt hái thành công lớn.', 'assets/cards/pentacles_14.jpg') ON DUPLICATE KEY UPDATE `name_vi` = VALUES(`name_vi`), `name_en` = VALUES(`name_en`), `arcana_type` = VALUES(`arcana_type`), `suit_element` = VALUES(`suit_element`), `keywords` = VALUES(`keywords`), `upright_meaning` = VALUES(`upright_meaning`), `reversed_meaning` = VALUES(`reversed_meaning`), `archetype_story` = VALUES(`archetype_story`), `yes_no_result` = VALUES(`yes_no_result`), `yes_no_reason` = VALUES(`yes_no_reason`), `time_prediction` = VALUES(`time_prediction`), `image_path` = VALUES(`image_path`);

-- ------------------------------------------------------------------------------
-- 2. NẠP BẢN GHI MẪU PHIÊN TRẢI BÀI VÀO BẢNG: ReadingSession (Tracking KMS)
-- ------------------------------------------------------------------------------
INSERT INTO `ReadingSession` (
    `session_id`,
    `user_question`,
    `topic`,
    `card_1_id`,
    `card_2_id`,
    `card_3_id`,
    `reading_result`,
    `created_at`
) VALUES (
    'session-kms-sample-01',
    'Tôi có nên bắt đầu dự án khởi nghiệp công nghệ trong tháng này không và khi nào sự việc sẽ đạt được kết quả thuận lợi?',
    'work',
    'major-0',
    'wands-1',
    'major-1',
    '【BÁO CÁO PHIÊN TRẢI BÀI TAROTCUAHALLE - HỆ THỐNG TRI THỨC 3 NGUỒN】\n\n1. QUYẾT ĐỊNH YES/NO TỔNG HỢP: YES (Khẳng định mạnh mẽ)\n- Lý giải tâm lý: Lá The Fool mở ra tiềm năng vô hạn, Ace of Wands bùng cháy ngọn lửa nhiệt huyết và The Magician khẳng định bạn đã hội tụ đầy đủ nguồn lực cùng kỹ năng để biến ý niệm thành hiện thực.\n\n2. MỐC THỜI GIAN DỰ ĐOÁN (Theo Philippe Ngô):\n- Khởi phát: Ngay lập tức trong vòng vài ngày tới (Ace of Wands - Lửa/Ngày).\n- Đạt đỉnh thành tựu: Chu kỳ mùa xuân hoặc trong vòng 1 - 2 tuần khi bắt tay vào hành động cụ thể.\n\n3. BÀI HỌC NGUYÊN MẪU & HÀNH TRÌNH TÂM THỨC:\n- Căn nguyên (The Fool): Đứa trẻ thuần khiết dám bước ra khỏi vùng an toàn.\n- Hiện tại (Ace of Wands): Ngọn lửa ý chí đã được vũ trụ trao tận tay.\n- Tương lai (The Magician): Làm chủ 4 nguyên tố để định hình thực tại thành công.',
    NOW()
) ON DUPLICATE KEY UPDATE
    `user_question` = VALUES(`user_question`),
    `topic` = VALUES(`topic`),
    `reading_result` = VALUES(`reading_result`);

SET FOREIGN_KEY_CHECKS = 1;
